# Verifier
# ---------------------------------------------------------------------------


class Verifier:
    """Runs structural verification over an operation tree."""

    @staticmethod
    def verify(op: Operation, raise_on_error: bool = False) -> List[str]:
        errors = op.verify()
        errors.extend(Verifier._verify_dominance(op))
        if errors and raise_on_error:
            raise VerificationError("; ".join(errors))
        return errors

    @staticmethod
    def _verify_dominance(root: Operation) -> List[str]:
        """Check that values are defined before use inside each single block.

        Multi-block regions are checked loosely (definition must appear in some
        block of the enclosing region or an ancestor), which is enough to catch
        the mistakes the parser and the rewriters can make.  Graph regions -
        which is what the hardware dialects use - are exempt, because there a
        value may legitimately be used above its definition.
        """
        errors: List[str] = []

        def _preceding(block: Block, op: Operation) -> List[Operation]:
            index = block.operations.index(op)
            return block.operations[:index]

        def check_block(block: Block) -> None:
            for op in block.operations:
                for value in op.operands:
                    if isinstance(value, OpResult):
                        owner = value.owner
                        if owner.parent is block and owner not in _preceding(block, op):
                            errors.append(
                                f"operand of '{op.name}' does not dominate its use"
                            )

        def visit(op: Operation) -> None:
            if op.has_trait(Trait.GRAPH_REGION):
                return
            for region in op.regions:
                for block in region.blocks:
                    check_block(block)

        root.walk(visit)
        return errors

"""Textual MLIR printer.

The printer is the inverse of :mod:`src.mlir.parser`: everything it emits parses
back into equivalent IR.  It prints the custom (pretty) assembly for the
operations the stack models and falls back to MLIR's generic form otherwise.
"""
from __future__ import annotations

import io
from typing import Dict, List, Optional, Sequence

from .ir import (
    ArrayAttr,
    Attribute,
    Block,
    BlockArgument,
    FlatSymbolRefAttr,
    FunctionType,
    IntegerAttr,
    IntegerType,
    ModuleOp,
    OpResult,
    Operation,
    Region,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    Value,
)

__all__ = [
    "SSANameState",
    "Printer",
    "print_op",
    "print_operation",
    "print_module",
]

#: Attributes that are part of the custom assembly and must not be repeated in
#: the trailing ``{...}`` dictionary.
_ELIDED_ATTRIBUTES = frozenset(
    {
        "sym_name",
        "function_type",
        "value",
        "predicate",
        "callee",
        "port_names",
        "port_directions",
        "assembly_keywords",
        "operand_segment_sizes",
    }
)

#: Operations printed as ``name <keyword> <operands> : <operand type>``.
_KEYWORD_FIRST_OPS = {"arith.cmpi", "arith.cmpf", "comb.icmp"}

#: Operations whose trailing type is the type of operand 0 rather than a result.
_PRINT_OPERAND_TYPE_OPS = _KEYWORD_FIRST_OPS


class SSANameState:
    """Assigns stable ``%0``/``^bb0`` names while printing."""

    def __init__(self, preserve_names: bool = True) -> None:
        self.preserve_names = preserve_names
        self._value_names: Dict[int, str] = {}
        self._block_names: Dict[int, str] = {}
        self._next_value = 0
        self._next_block = 0
        self._used: set = set()

    def get_value_name(self, value: Value) -> str:
        key = id(value)
        existing = self._value_names.get(key)
        if existing is not None:
            return existing
        name: Optional[str] = None
        if self.preserve_names and getattr(value, "name", None):
            candidate = f"%{value.name}"
            if candidate not in self._used:
                name = candidate
        if name is None:
            while f"%{self._next_value}" in self._used:
                self._next_value += 1
            name = f"%{self._next_value}"
            self._next_value += 1
        self._used.add(name)
        self._value_names[key] = name
        return name

    def set_value_name(self, value: Value, name: str) -> None:
        self._value_names[id(value)] = name
        self._used.add(name)

    def get_block_name(self, block: Block) -> str:
        key = id(block)
        existing = self._block_names.get(key)
        if existing is not None:
            return existing
        if self.preserve_names and block.label:
            name = f"^{block.label}"
        else:
            name = f"^bb{self._next_block}"
        self._next_block += 1
        self._block_names[key] = name
        return name


class Printer:
    """Renders an :class:`~src.mlir.ir.Operation` tree as MLIR text."""

    def __init__(self, indent_size: int = 2, preserve_names: bool = True) -> None:
        self._indent_size = indent_size
        self._indent_level = 0
        self._output = io.StringIO()
        self._name_state = SSANameState(preserve_names=preserve_names)

    # -- public API -------------------------------------------------------
    def print_operation(self, op: Operation) -> str:
        self._output = io.StringIO()
        self._indent_level = 0
        self._print_op(op)
        return self._output.getvalue().rstrip("\n")

    print_op = print_operation

    def print_module(self, module: Operation) -> str:
        return self.print_operation(module)

    # -- emit helpers -----------------------------------------------------
    def _write(self, text: str) -> None:
        self._output.write(text)

    def _write_line(self, text: str) -> None:
        self._output.write(" " * (self._indent_level * self._indent_size))
        self._output.write(text)
        self._output.write("\n")

    @property
    def _indent(self) -> str:
        return " " * (self._indent_level * self._indent_size)

    # -- operation printing -----------------------------------------------
    def _print_op(self, op: Operation) -> None:
        # Operations that are isolated from above (functions, hardware modules)
        # open a fresh SSA namespace, exactly as MLIR does, so ``%sum`` can be
        # reused in two sibling functions.
        saved_state: Optional[SSANameState] = None
        if op.has_trait(Trait.ISOLATED_FROM_ABOVE) and op.name != "builtin.module":
            saved_state = self._name_state
            self._name_state = SSANameState(preserve_names=saved_state.preserve_names)
        try:
            header = self._format_op_header(op)
            if op.regions and any(r.blocks for r in op.regions):
                self._write_line(header + " {")
                for region in op.regions:
                    self._print_region(region)
                self._write_line("}")
            else:
                self._write_line(header)
        finally:
            if saved_state is not None:
                self._name_state = saved_state

    def _format_op_header(self, op: Operation) -> str:
        if op.name in ("builtin.module",):
            sym = op.attributes.get("sym_name")
            return "module" + (f" @{sym.value}" if sym is not None else "")
        if op.name in ("func.func", "builtin.func"):
            return self._format_function_header(op)
        if op.name in ("hw.module", "hw.module.extern", "firrtl.module"):
            return self._format_hw_module_header(op)
        return self._format_generic_op(op)

    def _format_function_header(self, op: Operation) -> str:
        sym = op.attributes.get("sym_name")
        name = f"@{sym.value}" if sym is not None else "@unknown"
        block = op.regions[0].entry_block if op.regions else None
        args: List[str] = []
        if block is not None:
            for arg in block.arguments:
                args.append(f"{self._name_state.get_value_name(arg)}: {arg.type}")
        else:
            ftype = self._function_type(op)
            if ftype is not None:
                args = [str(t) for t in ftype.inputs]
        ftype = self._function_type(op)
        results = list(ftype.results) if ftype is not None else []
        text = f"{op.name} {name}({', '.join(args)})"
        if results:
            if len(results) == 1:
                text += f" -> {results[0]}"
            else:
                text += " -> (" + ", ".join(str(t) for t in results) + ")"
        return text

    def _format_hw_module_header(self, op: Operation) -> str:
        sym = op.attributes.get("sym_name")
        name = f"@{sym.value}" if sym is not None else "@unknown"
        port_names = op.attributes.get("port_names")
        port_dirs = op.attributes.get("port_directions")
        ftype = self._function_type(op)
        entries: List[str] = []
        if isinstance(port_names, ArrayAttr) and isinstance(port_dirs, ArrayAttr):
            block = op.regions[0].entry_block if op.regions else None
            input_index = 0
            output_types = list(ftype.results) if ftype is not None else []
            output_index = 0
            for name_attr, dir_attr in zip(port_names, port_dirs):
                direction = dir_attr.value
                if direction in ("in", "inout"):
                    if block is not None and input_index < len(block.arguments):
                        arg = block.arguments[input_index]
                        rendered = self._name_state.get_value_name(arg)
                        ptype = arg.type
                    else:
                        rendered = f"%{name_attr.value}"
                        ptype = (ftype.inputs[input_index] if ftype and
                                 input_index < len(ftype.inputs) else None)
                    entries.append(f"{direction} {rendered}: {ptype}")
                    input_index += 1
                else:
                    ptype = (output_types[output_index]
                             if output_index < len(output_types) else None)
                    entries.append(f"out {name_attr.value}: {ptype}")
                    output_index += 1
        return f"{op.name} {name}({', '.join(entries)})"

    def _function_type(self, op: Operation) -> Optional[FunctionType]:
        attr = op.attributes.get("function_type")
        if attr is None:
            return None
        value = attr.value
        return value if isinstance(value, FunctionType) else None

    def _format_generic_op(self, op: Operation) -> str:
        pieces: List[str] = []
        if op.num_results:
            names = [self._name_state.get_value_name(r) for r in op.results]
            pieces.append(", ".join(names) + " =")
        pieces.append(op.name)

        callee = op.attributes.get("callee")
        if isinstance(callee, FlatSymbolRefAttr):
            pieces.append(f"@{callee.value}")
        elif op.attributes.get("sym_name") is not None and not op.regions:
            pieces.append(f"@{op.attributes['sym_name'].value}")

        if op.name in _KEYWORD_FIRST_OPS:
            predicate = op.attributes.get("predicate")
            if predicate is not None:
                separator = "," if op.name.startswith("arith.") else ""
                pieces.append(f"{predicate.value}{separator}")
        keywords = op.attributes.get("assembly_keywords")

        value_attr = op.attributes.get("value")
        if value_attr is not None and not op.num_operands:
            pieces.append(self._format_value_attribute(value_attr))

        operand_texts = [self._render_operand(v) for v in op.operands]
        if op.name == "seq.compreg" and len(operand_texts) >= 4:
            pieces.append(", ".join(operand_texts[:2]))
            pieces.append("reset")
            pieces.append(", ".join(operand_texts[2:]))
        elif operand_texts:
            pieces.append(", ".join(operand_texts))
        elif isinstance(keywords, ArrayAttr) and op.name not in _KEYWORD_FIRST_OPS:
            pieces.extend(k.value for k in keywords)

        if op.successors:
            succ = ", ".join(self._name_state.get_block_name(b) for b in op.successors)
            if operand_texts:
                pieces[-1] = pieces[-1] + ","
            pieces.append(succ)

        attr_text = self._format_attributes(op.attributes)
        if attr_text:
            pieces.append(attr_text)

        type_text = self._format_trailing_type(op)
        if type_text:
            pieces.append(type_text)

        return " ".join(p for p in pieces if p)

    def _format_value_attribute(self, attr: Attribute) -> str:
        if isinstance(attr, IntegerAttr):
            return str(attr.value)
        if isinstance(attr, StringAttr):
            return str(attr)
        return str(attr)

    def _render_operand(self, operand: object) -> str:
        """Render an operand, tolerating behaviourally-built signal names."""
        if isinstance(operand, Value):
            return self._name_state.get_value_name(operand)
        return f"%{operand}"

    def _operand_type_text(self, op: Operation) -> Optional[str]:
        for operand in op.operands:
            if isinstance(operand, Value):
                return str(operand.type)
        return None

    def _format_attributes(self, attrs: Dict[str, Attribute]) -> str:
        visible = {k: v for k, v in attrs.items() if k not in _ELIDED_ATTRIBUTES}
        if not visible:
            return ""
        inner = ", ".join(f"{k} = {v}" for k, v in visible.items())
        return "{" + inner + "}"

    def _format_trailing_type(self, op: Operation) -> str:
        if op.name in _PRINT_OPERAND_TYPE_OPS and op.num_operands:
            operand_type = self._operand_type_text(op)
            if operand_type is not None:
                return f": {operand_type}"
        if op.num_results:
            types = [str(t) for t in op.result_types]
            unique = sorted(set(types))
            if len(unique) == 1:
                return f": {types[0]}"
            return ": " + ", ".join(types)
        if op.num_operands and op.name not in ("cf.br", "cf.cond_br", "cf.switch"):
            operand_type = self._operand_type_text(op)
            if operand_type is not None:
                return f": {operand_type}"
        return ""

    # -- regions / blocks -------------------------------------------------
    def _print_region(self, region: Region) -> None:
        self._indent_level += 1
        for index, block in enumerate(region.blocks):
            self._print_block(block, is_entry=index == 0)
        self._indent_level -= 1

    def _print_block(self, block: Block, is_entry: bool) -> None:
        if not is_entry:
            label = self._name_state.get_block_name(block)
            args = ""
            if block.arguments:
                rendered = ", ".join(
                    f"{self._name_state.get_value_name(a)}: {a.type}"
                    for a in block.arguments
                )
                args = f"({rendered})"
            # Block labels sit one level out from the operations they head.
            self._indent_level -= 1
            self._write_line(f"{label}{args}:")
            self._indent_level += 1
        for op in block.operations:
            self._print_op(op)


# ---------------------------------------------------------------------------
# Module-level helpers
# ---------------------------------------------------------------------------


def print_op(op: Operation, indent_size: int = 2, preserve_names: bool = True) -> str:
    """Render ``op`` (and everything nested in it) as MLIR text."""
    return Printer(indent_size=indent_size, preserve_names=preserve_names).print_operation(op)


#: Alias matching MLIR's C++ spelling.
print_operation = print_op


def print_module(module: Operation, indent_size: int = 2) -> str:
    return print_op(module, indent_size=indent_size)

"""The CIRCT ``hw`` dialect: modules, ports, constants and structural types.

The operations here are ordinary :class:`~src.mlir.ir.Operation` subclasses
registered against the shared MLIR context, which is what lets the parser in
:mod:`src.mlir.parser` read ``inputs/alu.mlir`` and ``inputs/counter.mlir``
directly.

Every value-producing operation also implements ``evaluate(env)``, the hook the
cycle-accurate simulator in :mod:`src.circt.simulator` drives.  ``env`` maps
either SSA :class:`~src.mlir.ir.Value` objects (IR mode) or plain signal names
(behavioural mode) to integers, so the same operation classes can be used to
build a circuit by hand without going through text.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Sequence, Tuple, Union

from mlir.ir import (
    ArrayAttr,
    Attribute,
    Block,
    Dialect,
    FunctionType,
    IntegerAttr,
    IntegerType,
    Location,
    Operation,
    OpaqueType,
    Region,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    Value,
    get_default_context,
)

__all__ = [
    "HW_DIALECT",
    "Direction",
    "IntType",
    "ArrayType",
    "StructType",
    "InOutType",
    "Port",
    "HWOp",
    "HWModuleOp",
    "HWModuleExternOp",
    "InstanceOp",
    "OutputOp",
    "WireOp",
    "ConstantOp",
    "ArrayCreateOp",
    "ArrayGetOp",
    "StructCreateOp",
    "StructExtractOp",
    "BitcastOp",
]

HW_DIALECT = Dialect("hw", get_default_context())

#: An environment maps SSA values *or* signal names to integers.
SignalEnv = Dict[Any, int]


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


class Direction(Enum):
    """Port direction, spelled as it appears in the textual IR."""

    INPUT = "in"
    OUTPUT = "out"
    INOUT = "inout"

    @staticmethod
    def parse(text: Union[str, "Direction"]) -> "Direction":
        if isinstance(text, Direction):
            return text
        for candidate in Direction:
            if candidate.value == text or candidate.name.lower() == str(text).lower():
                return candidate
        raise ValueError(f"unknown port direction {text!r}")


class IntType(IntegerType):
    """``iN`` as spelled by the hardware dialects (always signless)."""

    def __init__(self, width: int) -> None:
        if width <= 0:
            raise ValueError(f"hardware integer width must be positive, got {width}")
        super().__init__(width, "signless")

    def bit_count(self) -> int:
        return self.width

    def max_value(self) -> int:
        return (1 << self.width) - 1

    def mask(self) -> int:
        return (1 << self.width) - 1

    def __repr__(self) -> str:
        return f"i{self.width}"


class ArrayType(Type):
    """``!hw.array<Nxi8>``."""

    def __init__(self, element_type: Type, size: int) -> None:
        if size <= 0:
            raise ValueError(f"array size must be positive, got {size}")
        self.element_type = element_type
        self.size = int(size)

    def __str__(self) -> str:
        return f"!hw.array<{self.size}x{self.element_type}>"

    def __repr__(self) -> str:
        return str(self)

    def bit_count(self) -> int:
        return self.size * bit_width_of(self.element_type)

    def element_at(self, index: int) -> Type:
        if index < 0 or index >= self.size:
            raise IndexError(f"array index {index} out of range for size {self.size}")
        return self.element_type


class StructType(Type):
    """``!hw.struct<name: type, ...>``."""

    def __init__(self, fields: Optional[Sequence[Tuple[str, Type]]] = None) -> None:
        self.fields: List[Tuple[str, Type]] = list(fields or ())

    def __str__(self) -> str:
        inner = ", ".join(f"{name}: {ftype}" for name, ftype in self.fields)
        return f"!hw.struct<{inner}>"

    def __repr__(self) -> str:
        return str(self)

    def bit_count(self) -> int:
        return sum(bit_width_of(ftype) for _, ftype in self.fields)

    def get_field_type(self, name: str) -> Optional[Type]:
        for field_name, ftype in self.fields:
            if field_name == name:
                return ftype
        return None

    def field_names(self) -> List[str]:
        return [name for name, _ in self.fields]


class InOutType(Type):
    """``!hw.inout<i8>``."""

    def __init__(self, inner_type: Type) -> None:
        self.inner_type = inner_type

    def __str__(self) -> str:
        return f"!hw.inout<{self.inner_type}>"

    def __repr__(self) -> str:
        return str(self)

    def bit_count(self) -> int:
        return bit_width_of(self.inner_type)


def bit_width_of(type: Optional[Type]) -> int:
    """Best-effort bit width for any hardware type."""
    if type is None:
        return 0
    for attribute in ("bit_count",):
        method = getattr(type, attribute, None)
        if callable(method):
            return int(method())
    width = type.bitwidth()
    return int(width) if width else 0


HW_DIALECT.register_type_parser("array", lambda body: OpaqueType("hw", "array", body))
HW_DIALECT.register_type_parser("struct", lambda body: OpaqueType("hw", "struct", body))
HW_DIALECT.register_type_parser("inout", lambda body: OpaqueType("hw", "inout", body))


# ---------------------------------------------------------------------------
# Ports
# ---------------------------------------------------------------------------


@dataclass
class Port:
    """One port of a hardware module."""

    name: str
    port_type: Optional[Type] = None
    direction: Direction = Direction.INPUT

    def __post_init__(self) -> None:
        self.direction = Direction.parse(self.direction)

    @property
    def is_input(self) -> bool:
        return self.direction is Direction.INPUT

    @property
    def is_output(self) -> bool:
        return self.direction is Direction.OUTPUT

    @property
    def is_inout(self) -> bool:
        return self.direction is Direction.INOUT

    def bit_width(self) -> int:
        return bit_width_of(self.port_type)

    def __repr__(self) -> str:
        return f"Port({self.direction.value} {self.name}: {self.port_type})"


# ---------------------------------------------------------------------------
# Operation base
# ---------------------------------------------------------------------------


class HWOp(Operation):
    """Shared behaviour for hardware operations.

    Hardware operations can be built two ways:

    * from the parser, where operands are real SSA :class:`Value` objects, or
    * *behaviourally*, by passing operand **names** as strings.

    ``read_operand`` hides the difference so simulators and folders work with
    either representation.
    """

    OPERATION_NAME: Optional[str] = None

    #: Set when the operation was built from signal names rather than SSA values.
    _symbolic_operands: Optional[List[str]] = None
    #: Declared result width (used when there is no result type to read).
    _declared_width: int = 0
    #: Preferred name for the result, mirroring CIRCT's ``result_name``.
    result_name: str = ""

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        width: int = 0,
        result_name: str = "",
        name: Optional[str] = None,
        location: Optional[Location] = None,
        successors: Optional[Sequence[Block]] = None,
        regions: Optional[Sequence[Region]] = None,
    ) -> None:
        raw = list(operands or ())
        symbolic = [item for item in raw if isinstance(item, str)]
        values = [item for item in raw if isinstance(item, Value)]
        if symbolic and values:
            raise ValueError("cannot mix SSA values and signal names in one operation")

        types = list(result_types or ())
        if not types and width:
            types = [IntType(width)] * self.default_num_results()

        super().__init__(
            name=name or self.operation_name(),
            operands=values,
            result_types=types,
            attributes=attributes,
            successors=successors,
            regions=regions,
            location=location,
            result_names=[result_name] if result_name else None,
        )
        self._symbolic_operands = symbolic or None
        self._declared_width = int(width)
        self.result_name = result_name

    # -- construction helpers ---------------------------------------------
    @classmethod
    def default_num_results(cls) -> int:
        return 1

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> "Operation":
        op = cls.__new__(cls)
        Operation.__init__(op, **kwargs)
        op._symbolic_operands = None
        op._declared_width = 0
        results = kwargs.get("result_names") or []
        op.result_name = next((r for r in results if r), "")
        return op

    # -- operand access ---------------------------------------------------
    @property
    def operands(self) -> List[Any]:
        """SSA values, or signal names when built behaviourally."""
        if self._symbolic_operands is not None:
            return list(self._symbolic_operands)
        return Operation.operands.fget(self)  # type: ignore[attr-defined]

    @property
    def ssa_operands(self) -> List[Value]:
        return Operation.operands.fget(self)  # type: ignore[attr-defined]

    @property
    def operand_names(self) -> List[str]:
        if self._symbolic_operands is not None:
            return list(self._symbolic_operands)
        return [v.name or f"%{index}" for index, v in enumerate(self.ssa_operands)]

    @property
    def num_operands(self) -> int:
        if self._symbolic_operands is not None:
            return len(self._symbolic_operands)
        return Operation.num_operands.fget(self)  # type: ignore[attr-defined]

    def get_operand(self, index: int) -> Any:
        operands = self.operands
        if index < 0 or index >= len(operands):
            raise IndexError(f"operand index {index} out of range")
        return operands[index]

    def read_operand(self, env: SignalEnv, index: int, default: int = 0) -> int:
        """Read operand ``index`` out of ``env``."""
        if self._symbolic_operands is not None:
            if index >= len(self._symbolic_operands):
                return default
            key = self._symbolic_operands[index]
            return int(env.get(key, default))
        values = self.ssa_operands
        if index >= len(values):
            return default
        value = values[index]
        if value in env:
            return int(env[value])
        if value.name is not None and value.name in env:
            return int(env[value.name])
        return default

    def read_operands(self, env: SignalEnv) -> List[int]:
        return [self.read_operand(env, i) for i in range(self.num_operands)]

    # -- widths -----------------------------------------------------------
    @property
    def width(self) -> int:
        if self.num_results:
            return bit_width_of(Operation.results.fget(self)[0].type)  # type: ignore[attr-defined]
        return self._declared_width

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return self.width

    def mask(self) -> int:
        width = self.width
        return (1 << width) - 1 if width > 0 else 0

    def truncate(self, value: int) -> int:
        mask = self.mask()
        return value & mask if mask else int(value)

    # -- evaluation -------------------------------------------------------
    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        raise NotImplementedError(f"{self.name} does not implement evaluate()")

    def fold(self) -> Optional[List[Any]]:
        """Constant-fold using the operands' ``hw.constant`` definitions."""
        if self._symbolic_operands is not None or not self.num_results:
            return None
        env: SignalEnv = {}
        for value in self.ssa_operands:
            defining = value.defining_op
            if defining is None or not isinstance(defining, ConstantOp):
                return None
            env[value] = defining.evaluate()
        try:
            return [self.evaluate(env)]
        except (NotImplementedError, ZeroDivisionError):
            return None


# ---------------------------------------------------------------------------
# Operations
# ---------------------------------------------------------------------------


class HWModuleOp(HWOp):
    """``hw.module @Name(in %a: i4, out r: i4) { ... }``.

    The body is a *graph region*: operations may refer to values defined further
    down, which is how ``inputs/counter.mlir`` closes the loop between
    ``seq.compreg`` and the ``comb.add`` that feeds it.
    """

    OPERATION_NAME = "hw.module"
    TRAITS = (
        Trait.SYMBOL,
        Trait.ISOLATED_FROM_ABOVE,
        Trait.GRAPH_REGION,
        Trait.SINGLE_BLOCK,
    )

    def __init__(
        self,
        name: Optional[str] = None,
        ports: Optional[Sequence[Port]] = None,
        body: Optional[Sequence[Operation]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        port_list = list(ports or ())
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs["sym_name"] = StringAttr(name)
        attrs["port_names"] = ArrayAttr([StringAttr(p.name) for p in port_list])
        attrs["port_directions"] = ArrayAttr(
            [StringAttr(p.direction.value) for p in port_list]
        )
        attrs["function_type"] = TypeAttr(
            FunctionType(
                [p.port_type for p in port_list if not p.is_output and p.port_type],
                [p.port_type for p in port_list if p.is_output and p.port_type],
            )
        )
        Operation.__init__(
            self,
            name=self.OPERATION_NAME,
            attributes=attrs,
            location=location,
        )
        self._symbolic_operands = None
        self._declared_width = 0
        self.result_name = ""

        region = self.add_region(Region())
        block = region.add_block(Block())
        for port in port_list:
            if not port.is_output:
                block.add_argument(port.port_type or IntType(1), port.name)
        for op in body or ():
            if isinstance(op, Operation):
                block.append(op)

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> "Operation":
        op = cls.__new__(cls)
        Operation.__init__(op, **kwargs)
        op._symbolic_operands = None
        op._declared_width = 0
        op.result_name = ""
        return op

    # -- structure --------------------------------------------------------
    @property
    def module_name(self) -> Optional[str]:
        attr = self.attributes.get("sym_name")
        return attr.value if attr is not None else None

    #: CIRCT spells the symbol ``name``; :class:`Operation` uses that for the
    #: op mnemonic, so the module symbol is exposed as ``module_name`` too.
    @property
    def sym_name(self) -> Optional[str]:
        return self.module_name

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        """The operations in the module body, in textual order."""
        block = self.block
        return list(block.operations) if block is not None else []

    @property
    def ports(self) -> List[Port]:
        names = self.attributes.get("port_names")
        directions = self.attributes.get("port_directions")
        ftype = self.attributes.get("function_type")
        signature = ftype.value if ftype is not None else None
        if not isinstance(names, ArrayAttr) or not isinstance(directions, ArrayAttr):
            return []
        inputs = list(signature.inputs) if signature is not None else []
        outputs = list(signature.results) if signature is not None else []
        result: List[Port] = []
        in_index = out_index = 0
        for name_attr, dir_attr in zip(names, directions):
            direction = Direction.parse(dir_attr.value)
            if direction is Direction.OUTPUT:
                ptype = outputs[out_index] if out_index < len(outputs) else None
                out_index += 1
            else:
                ptype = inputs[in_index] if in_index < len(inputs) else None
                in_index += 1
            result.append(Port(name_attr.value, ptype, direction))
        return result

    @property
    def input_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_input]

    @property
    def output_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_output]

    @property
    def inout_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_inout]

    def get_port(self, name: str) -> Optional[Port]:
        for port in self.ports:
            if port.name == name:
                return port
        return None

    def total_input_bits(self) -> int:
        return sum(p.bit_width() for p in self.input_ports)

    def total_output_bits(self) -> int:
        return sum(p.bit_width() for p in self.output_ports)

    @property
    def output_op(self) -> Optional[Operation]:
        for op in reversed(self.body):
            if op.name == "hw.output":
                return op
        return None

    # -- verification -----------------------------------------------------
    def verify_signature(self) -> List[str]:
        errors: List[str] = []
        seen: set = set()
        for port in self.ports:
            if port.name in seen:
                errors.append(f"Duplicate port name: {port.name}")
            seen.add(port.name)
            if port.bit_width() == 0:
                errors.append(f"Port {port.name} has zero width")
        output = self.output_op
        expected = len(self.output_ports)
        if output is not None and output.num_operands != expected:
            errors.append(
                f"OutputOp has {output.num_operands} operands but module has "
                f"{expected} output ports"
            )
        return errors

    def verify_op(self) -> List[str]:
        errors = list(self.verify_signature())
        if self.module_name is None:
            errors.append("'hw.module' requires a 'sym_name' attribute")
        return errors


class HWModuleExternOp(HWModuleOp):
    """``hw.module.extern`` - a declaration with no body."""

    OPERATION_NAME = "hw.module.extern"


class ConstantOp(HWOp):
    """``hw.constant 5 : i4``."""

    OPERATION_NAME = "hw.constant"
    TRAITS = (Trait.PURE, Trait.CONSTANT_LIKE)

    def __init__(
        self,
        value: Optional[int] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        types = list(result_types or ())
        if not types:
            types = [IntType(width if width > 0 else 32)]
        if value is not None:
            attrs.setdefault("value", IntegerAttr(int(value), types[0]))
        super().__init__(
            result_types=types,
            attributes=attrs,
            width=width,
            result_name=result_name,
            location=location,
        )

    @property
    def value(self) -> int:
        attr = self.attributes.get("value")
        if attr is None:
            return 0
        raw = attr.value
        return int(raw) if isinstance(raw, (int, float)) else 0

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.truncate(self.value)

    def fold(self) -> Optional[List[Any]]:
        return [self.evaluate()]

    def is_zero(self) -> bool:
        return self.evaluate() == 0

    def is_all_ones(self) -> bool:
        return self.evaluate() == self.mask()


class OutputOp(HWOp):
    """``hw.output %a, %b : i4, i4`` - the module terminator."""

    OPERATION_NAME = "hw.output"
    TRAITS = (Trait.TERMINATOR, Trait.PURE)

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
