    TRAITS = (Trait.PURE, Trait.COMMUTATIVE)
    REDUCER = staticmethod(lambda a, b: a ^ b)


class DivUOp(CombOp):
    OPERATION_NAME = "comb.divu"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        if rhs == 0:
            return self.mask()
        return self.truncate(lhs // rhs)


class DivSOp(CombOp):
    OPERATION_NAME = "comb.divs"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        width = self.width
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        signed_lhs = _to_signed(lhs, width)
        signed_rhs = _to_signed(rhs, width)
        if signed_rhs == 0:
            return self.mask()
        quotient = abs(signed_lhs) // abs(signed_rhs)
        if (signed_lhs < 0) != (signed_rhs < 0):
            quotient = -quotient
        return self.truncate(quotient)


class ModUOp(CombOp):
    OPERATION_NAME = "comb.modu"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        if rhs == 0:
            return 0
        return self.truncate(lhs % rhs)


class ModSOp(CombOp):
    OPERATION_NAME = "comb.mods"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        width = self.width
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        signed_lhs = _to_signed(lhs, width)
        signed_rhs = _to_signed(rhs, width)
        if signed_rhs == 0:
            return 0
        remainder = abs(signed_lhs) % abs(signed_rhs)
        if signed_lhs < 0:
            remainder = -remainder
        return self.truncate(remainder)


class ShlOp(CombOp):
    OPERATION_NAME = "comb.shl"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        return self.truncate(lhs << rhs)


class ShrUOp(CombOp):
    OPERATION_NAME = "comb.shru"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        return self.truncate(lhs >> rhs)


class ShrSOp(CombOp):
    OPERATION_NAME = "comb.shrs"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        width = self.width
        lhs, rhs = (self.read_operands(env or {}) + [0, 0])[:2]
        return self.truncate(_to_signed(lhs, width) >> rhs)


class MuxOp(CombOp):
    """``comb.mux %cond, %true, %false : i4``."""

    OPERATION_NAME = "comb.mux"

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        values = self.read_operands(env or {})
        if len(values) < 3:
            raise NotImplementedError("comb.mux needs cond, true and false operands")
        condition, when_true, when_false = values[0], values[1], values[2]
        return self.truncate(when_true if condition & 1 else when_false)

    def verify_op(self) -> List[str]:
        if self.num_operands != 3:
            return [f"'comb.mux' expects 3 operands, got {self.num_operands}"]
        return []


#: ``comb.icmp`` predicates.  Signed variants reinterpret the operands.
ICMP_PREDICATES: Dict[str, Callable[[int, int], bool]] = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "ult": lambda a, b: a < b,
    "ule": lambda a, b: a <= b,
    "ugt": lambda a, b: a > b,
    "uge": lambda a, b: a >= b,
    "slt": lambda a, b: a < b,
    "sle": lambda a, b: a <= b,
    "sgt": lambda a, b: a > b,
    "sge": lambda a, b: a >= b,
}

_SIGNED_PREDICATES = frozenset({"slt", "sle", "sgt", "sge"})


class ICmpOp(CombOp):
    """``comb.icmp eq %a, %b : i2`` producing an ``i1``."""

    OPERATION_NAME = "comb.icmp"

    def __init__(
        self,
        predicate: str = "eq",
        operands: Optional[Sequence[Union[Value, str]]] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        attrs.setdefault("predicate", StringAttr(predicate))
        super().__init__(
            operands=operands,
            result_types=list(result_types or ()) or [IntegerType(1)],
            attributes=attrs,
            width=width,
            result_name=result_name,
            location=location,
        )
        #: The operand width; the *result* is always one bit.
        self.operand_width = int(width)

    @classmethod
    def result_types_from_trailing(
        cls, trailing_types: Sequence[Type], num_results: int
    ) -> List[Type]:
        return [IntegerType(1)] * num_results

    @property
    def predicate(self) -> str:
        attr = self.attributes.get("predicate")
        return attr.value if attr is not None else "eq"

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return 1

    def _comparison_width(self) -> int:
        for operand in self.ssa_operands:
            width = bit_width_of(operand.type)
            if width:
                return width
        return self.operand_width

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        predicate = self.predicate
        compare = ICMP_PREDICATES.get(predicate)
        if compare is None:
            return 0
        values = self.read_operands(env or {})
        if len(values) < 2:
            return 0
        lhs, rhs = values[0], values[1]
        if predicate in _SIGNED_PREDICATES:
            width = self._comparison_width()
            lhs = _to_signed(lhs, width)
            rhs = _to_signed(rhs, width)
        return 1 if compare(lhs, rhs) else 0

    def verify_op(self) -> List[str]:
        if self.predicate not in ICMP_PREDICATES:
            return [f"'comb.icmp' has unknown predicate {self.predicate!r}"]
        return []


class ConcatOp(CombOp):
    """``comb.concat %hi, %lo`` - operand 0 becomes the most significant bits."""

    OPERATION_NAME = "comb.concat"

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        operand_widths: Optional[Sequence[int]] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=width,
            result_name=result_name,
            location=location,
        )
        self.operand_widths: List[int] = list(operand_widths or ())

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.operand_widths = []
        return op

    def _widths(self) -> List[int]:
        if self.operand_widths:
            return list(self.operand_widths)
        return [bit_width_of(v.type) for v in self.ssa_operands]

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        widths = self._widths()
        return sum(widths) if widths else self.width

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        values = self.read_operands(env or {})
        widths = self._widths()
        packed = 0
        for index, value in enumerate(values):
            width = widths[index] if index < len(widths) else 1
            packed = (packed << width) | (value & ((1 << width) - 1))
        total = sum(widths) if widths else self.width
        return packed & ((1 << total) - 1) if total else packed


class ExtractOp(CombOp):
    """``comb.extract %x from 3 : (i8) -> i4``."""

    OPERATION_NAME = "comb.extract"

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        low_bit: int = 0,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=width,
            result_name=result_name,
            location=location,
        )
        self.low_bit = int(low_bit)

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        low = kwargs.get("attributes", {}).get("lowBit")
        op.low_bit = int(low.value) if low is not None else 0
        return op

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        source = self.read_operand(env or {}, 0)
        return self.truncate(source >> self.low_bit)


class ReplicateOp(CombOp):
    """``comb.replicate %x : (i1) -> i4``."""

    OPERATION_NAME = "comb.replicate"

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        input_width: int = 0,
        count: int = 1,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=width,
            result_name=result_name,
            location=location,
        )
        self.input_width = int(input_width)
        self.count = int(count)

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.input_width = 0
        op.count = 1
        return op

    def _input_width(self) -> int:
        if self.input_width:
            return self.input_width
        for value in self.ssa_operands:
            width = bit_width_of(value.type)
            if width:
                return width
        return 1

    def _count(self) -> int:
        if self.num_results:
            source = self._input_width()
            if source:
                return max(1, self.width // source)
        return max(1, self.count)

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return self._input_width() * self._count()

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        source_width = self._input_width()
        source = self.read_operand(env or {}, 0) & ((1 << source_width) - 1)
        packed = 0
        for _ in range(self._count()):
            packed = (packed << source_width) | source
        total = self.width or (source_width * self._count())
        return packed & ((1 << total) - 1) if total else packed


class ParityOp(CombOp):
    """``comb.parity %x : (i8) -> i1`` - XOR reduction."""

    OPERATION_NAME = "comb.parity"

    @classmethod
    def result_types_from_trailing(
        cls, trailing_types: Sequence[Type], num_results: int
    ) -> List[Type]:
        return [IntegerType(1)] * num_results

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return 1

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        value = self.read_operand(env or {}, 0)
        parity = 0
        while value:
            parity ^= value & 1
            value >>= 1
        return parity


#: Every ``comb`` operation, keyed by its op name.
COMB_OPS: Dict[str, type] = {}
for _cls in (
    AddOp,
    SubOp,
    MulOp,
    DivUOp,
    DivSOp,
    ModUOp,
    ModSOp,
    AndOp,
    OrOp,
    XorOp,
    ShlOp,
    ShrUOp,
    ShrSOp,
    MuxOp,
    ICmpOp,
    ConcatOp,
    ExtractOp,
    ReplicateOp,
    ParityOp,
):
    COMB_DIALECT.register_operation(_cls)
    COMB_OPS[_cls.OPERATION_NAME] = _cls
del _cls

"""The CIRCT ``seq`` dialect: clocks, registers and other stateful elements.

Sequential operations are the only place where a cycle boundary matters, so they
expose a two-phase interface that the simulator drives:

* ``next_value(env)`` - what the element *would* latch, computed from the
  settled combinational values of the current cycle.
* ``commit(value)`` / ``tick(env)`` - advance the state to the next cycle.

Keeping the two separate is what makes the simulation cycle-accurate: every
register in a design samples the same pre-edge values.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Sequence, Union

from mlir.ir import (
    Attribute,
    Dialect,
    IntegerType,
    Location,
    Operation,
    OpaqueType,
    StringAttr,
    Trait,
    Type,
    Value,
    get_default_context,
)
from .hw_dialect import HW_DIALECT, HWOp, IntType, SignalEnv, bit_width_of

__all__ = [
    "SEQ_DIALECT",
    "ClockType",
    "ResetType",
    "ClockDomain",
    "SeqOp",
    "CompRegOp",
    "CompRegClockEnabledOp",
    "FirRegOp",
    "ShiftRegOp",
    "FIFOOp",
    "ClockGateOp",
    "HLMemOp",
    "FromClockOp",
    "ToClockOp",
    "SEQ_OPS",
]

SEQ_DIALECT = Dialect("seq", get_default_context())


class ClockType(OpaqueType):
    """The ``!seq.clock`` type."""

    def __init__(self) -> None:
        super().__init__("seq", "clock")


SEQ_DIALECT.register_type_parser("clock", lambda body: ClockType())


class ResetType(Enum):
    """How a register's reset input is sampled."""

    SYNC = "synchronous"
    ASYNC = "asynchronous"
    NONE = "none"


@dataclass
class ClockDomain:
    """A named clock with a frequency, used for timing bookkeeping."""

    name: str
    frequency_hz: float = 100e6
    rising_edge: bool = True
    period_ns: float = 0.0

    def __post_init__(self) -> None:
        if self.frequency_hz > 0:
            self.period_ns = 1e9 / self.frequency_hz

    def half_period_ns(self) -> float:
        return self.period_ns / 2.0

    def is_compatible(self, other: "ClockDomain") -> bool:
        return self.name == other.name


class SeqOp(HWOp):
    """Base class for stateful (clocked) operations."""

    OPERATION_NAME: Optional[str] = None
    TRAITS = (Trait.HAS_CLOCK,)

    #: Class-level defaults so ``build_parsed`` (which skips ``__init__``) works.
    reg_name: str = ""
    current_value: int = 0
    reset_value: int = 0
    reset_type: ResetType = ResetType.SYNC
    clock_domain: Optional[ClockDomain] = None
    cycles_ticked: int = 0

    # -- state ------------------------------------------------------------
    def get_value(self) -> int:
        return self.current_value

    def set_value(self, value: int) -> None:
        self.current_value = self.truncate(value)

    def reset_state(self) -> None:
        """Return the element to its power-on / reset state."""
        self.current_value = self.truncate(self.reset_value)
        self.cycles_ticked = 0

    def next_value(self, env: SignalEnv) -> int:
        """The value this element latches at the next clock edge."""
        raise NotImplementedError

    def commit(self, value: int) -> int:
        self.current_value = self.truncate(value)
        self.cycles_ticked += 1
        return self.current_value

    def tick(self, env: Optional[SignalEnv] = None) -> int:
        """Compute the next value and immediately commit it."""
        return self.commit(self.next_value(env or {}))

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        """A register reads as its *current* state, not its input."""
        return self.truncate(self.current_value)

    def fold(self) -> Optional[List[Any]]:
        return None


class CompRegOp(SeqOp):
    """``seq.compreg %next, %clk reset %reset, %resetValue : i8``.

    Operand order follows CIRCT: ``(input, clock[, reset, resetValue])``.
    """

    OPERATION_NAME = "seq.compreg"

    #: Operand indices.
    INPUT = 0
    CLOCK = 1
    RESET = 2
    RESET_VALUE = 3

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        clock: Union[Value, str] = "clk",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        reset_type: ResetType = ResetType.SYNC,
        current_value: int = 0,
        clock_domain: Optional[ClockDomain] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            if reset is not None:
                ops.append(reset)
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("name", StringAttr(name))
        super().__init__(
            operands=ops,
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.reset_value = int(reset_value)
        self.reset_type = reset_type
        self.current_value = int(current_value)
        self.clock_domain = clock_domain
        self.cycles_ticked = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        name_attr = kwargs.get("attributes", {}).get("name")
        op.reg_name = name_attr.value if name_attr is not None else op.result_name
        op.reset_type = ResetType.SYNC
        op.reset_value = 0
        op.current_value = 0
        op.clock_domain = None
        op.cycles_ticked = 0
        return op

    # -- operand accessors -------------------------------------------------
    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    @property
    def input_signal(self) -> Any:
        return self.get_operand(self.INPUT) if self.num_operands > self.INPUT else None

    @property
    def clock(self) -> Any:
        return self.get_operand(self.CLOCK) if self.num_operands > self.CLOCK else None

    @property
    def reset(self) -> Any:
        return self.get_operand(self.RESET) if self.has_reset else None

    def declared_reset_value(self, env: SignalEnv) -> int:
        """The reset value, read from the operand when the IR supplies one."""
        if self.num_operands > self.RESET_VALUE:
            return self.read_operand(env, self.RESET_VALUE)
        return self.reset_value

    def reset_active(self, env: SignalEnv) -> bool:
        if not self.has_reset:
            return False
        if self.reset_type is ResetType.NONE:
            return False
        return bool(self.read_operand(env, self.RESET) & 1)

    def async_reset(self, env: Optional[SignalEnv] = None) -> bool:
        env = env or {}
        return self.reset_type is ResetType.ASYNC and self.reset_active(env)

    # -- clocked behaviour -------------------------------------------------
    def next_value(self, env: SignalEnv) -> int:
        if self.reset_active(env):
            return self.truncate(self.declared_reset_value(env))
        return self.truncate(self.read_operand(env, self.INPUT))

    def reset_state(self, env: Optional[SignalEnv] = None) -> None:
        self.current_value = self.truncate(self.declared_reset_value(env or {}))
        self.cycles_ticked = 0

    def verify_op(self) -> List[str]:
        if self.num_operands < 2:
            return ["'seq.compreg' expects at least an input and a clock operand"]
        return []


class CompRegClockEnabledOp(CompRegOp):
    """``seq.compreg.ce`` - a register with an explicit clock enable."""

    OPERATION_NAME = "seq.compreg.ce"

    #: Operand indices (clock enable sits after the clock).
    CLOCK_ENABLE = 2
    RESET = 3
    RESET_VALUE = 4

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        clock: Union[Value, str] = "clk",
        clock_enable: Union[Value, str] = "ce",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        reset_type: ResetType = ResetType.SYNC,
        current_value: int = 0,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            ops.append(clock_enable)
            if reset is not None:
                ops.append(reset)
        super().__init__(
            name=name,
            width=width,
            reset_value=reset_value,
            reset_type=reset_type,
            current_value=current_value,
            operands=ops,
            result_types=result_types,
            location=location,
        )

    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    def is_enabled(self, env: Optional[SignalEnv] = None) -> bool:
        if self.num_operands <= self.CLOCK_ENABLE:
            return True
        return bool(self.read_operand(env or {}, self.CLOCK_ENABLE, default=1) & 1)

    def next_value(self, env: SignalEnv) -> int:
        if self.reset_active(env):
            return self.truncate(self.declared_reset_value(env))
        if not self.is_enabled(env):
            return self.truncate(self.current_value)
        return self.truncate(self.read_operand(env, self.INPUT))


class FirRegOp(SeqOp):
    """``seq.firreg`` - a FIRRTL-style register with an optional preset."""

    OPERATION_NAME = "seq.firreg"

    INPUT = 0
    CLOCK = 1
    RESET = 2
    RESET_VALUE = 3

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        clock: Union[Value, str] = "clk",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        preset_value: Optional[int] = None,
        current_value: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            if reset is not None:
                ops.append(reset)
        super().__init__(
            operands=ops,
            result_types=result_types,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.reset_value = int(reset_value)
        self.preset_value = preset_value
        self.current_value = int(preset_value if preset_value is not None else current_value)
        self.cycles_ticked = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.preset_value = None
        op.reset_value = 0
        op.current_value = 0
        op.cycles_ticked = 0
        return op

    def preset(self) -> None:
        if self.preset_value is not None:
            self.current_value = self.truncate(self.preset_value)

    def next_value(self, env: SignalEnv) -> int:
        if self.num_operands > self.RESET and self.read_operand(env, self.RESET) & 1:
            if self.num_operands > self.RESET_VALUE:
                return self.truncate(self.read_operand(env, self.RESET_VALUE))
            return self.truncate(self.reset_value)
        return self.truncate(self.read_operand(env, self.INPUT))

    def tick(self, env: Optional[SignalEnv] = None, next_value: Optional[int] = None) -> int:
        """Commit ``next_value`` if given, otherwise compute it from ``env``."""
        if next_value is not None:
            return self.commit(next_value)
        return self.commit(self.next_value(env or {}))


@dataclass
class ShiftRegOp:
    """``seq.shiftreg`` - a chain of ``length`` registers."""

    name: str
    width: int = 1
    length: int = 1
    clock: str = "clk"
    stages: List[int] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.stages:
            self.stages = [0] * self.length

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    def shift_in(self, value: int) -> int:
        """Push ``value`` in at stage 0 and return what falls out of the end."""
        shifted_out = self.stages[-1] if self.stages else 0
        self.stages = [int(value) & self.mask()] + self.stages[:-1]
        return shifted_out

    def peek(self, stage: int) -> int:
        if stage < 0 or stage >= len(self.stages):
            return 0
        return self.stages[stage]

    def reset_all(self) -> None:
        self.stages = [0] * self.length


@dataclass
class FIFOOp:
    """``seq.fifo`` - a circular-buffer FIFO."""

    name: str
    width: int = 32
    depth: int = 16
    clock: str = "clk"
    reset: Optional[str] = None
    buffer: List[int] = field(default_factory=list)
    read_ptr: int = 0
    write_ptr: int = 0
    count: int = 0

    def __post_init__(self) -> None:
        if not self.buffer:
            self.buffer = [0] * self.depth

    def is_full(self) -> bool:
        return self.count >= self.depth

    def is_empty(self) -> bool:
        return self.count == 0

    def occupancy(self) -> int:
        return self.count

    def push(self, value: int) -> bool:
        if self.is_full():
            return False
        self.buffer[self.write_ptr] = int(value) & ((1 << self.width) - 1)
        self.write_ptr = (self.write_ptr + 1) % self.depth
        self.count += 1
        return True

    def pop(self) -> Optional[int]:
        if self.is_empty():
            return None
        value = self.buffer[self.read_ptr]
        self.read_ptr = (self.read_ptr + 1) % self.depth
        self.count -= 1
        return value


@dataclass
class ClockGateOp:
    """``seq.clock_gate`` - gate a clock with an enable."""

    name: str
    clock_in: str = "clk"
    enable: str = "en"
    test_enable: str = ""
    is_active: bool = False

    def evaluate(self, env: Optional[Dict[str, int]] = None) -> bool:
        env = env or {}
        enabled = bool(env.get(self.enable, 0))
        if self.test_enable:
            enabled = enabled or bool(env.get(self.test_enable, 0))
        self.is_active = enabled
        return enabled

    def clock_output(self, clock_value: int, env: Optional[Dict[str, int]] = None) -> int:
        return int(clock_value) if self.evaluate(env) else 0


class HLMemOp(SeqOp):
    """``seq.hlmem`` - a synchronous memory."""

    OPERATION_NAME = "seq.hlmem"

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 32,
        depth: int = 16,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(
            operands=operands,
            result_types=result_types,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.depth = int(depth)
        self.storage: Dict[int, int] = {}

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.depth = 0
        op.storage = {}
        return op

    def read(self, address: int) -> int:
        return self.storage.get(int(address), 0)

    def write(self, address: int, value: int) -> None:
        self.storage[int(address)] = self.truncate(value)

    def next_value(self, env: SignalEnv) -> int:
        return self.current_value


class FromClockOp(HWOp):
    """``seq.from_clock`` - reinterpret a ``!seq.clock`` as ``i1``."""

    OPERATION_NAME = "seq.from_clock"
    TRAITS = (Trait.PURE,)

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.read_operand(env or {}, 0) & 1


class ToClockOp(HWOp):
    """``seq.to_clock`` - reinterpret an ``i1`` as a ``!seq.clock``."""

    OPERATION_NAME = "seq.to_clock"
    TRAITS = (Trait.PURE,)

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.read_operand(env or {}, 0) & 1


#: Every stateful ``seq`` operation that participates in simulation.
SEQ_OPS: Dict[str, type] = {}
for _cls in (
    CompRegOp,
    CompRegClockEnabledOp,
    FirRegOp,
    HLMemOp,
    FromClockOp,
    ToClockOp,
):
    SEQ_DIALECT.register_operation(_cls)
    SEQ_OPS[_cls.OPERATION_NAME] = _cls
del _cls

#: Operation names whose instances hold state across clock cycles.
STATEFUL_OP_NAMES = frozenset(
    {CompRegOp.OPERATION_NAME, CompRegClockEnabledOp.OPERATION_NAME,
     FirRegOp.OPERATION_NAME, HLMemOp.OPERATION_NAME}
)

"""Cycle-accurate simulator for ``hw``/``comb``/``seq`` circuits.

The simulator walks the IR produced by :mod:`src.mlir.parser`, so the circuits in
``inputs/alu.mlir`` and ``inputs/counter.mlir`` are simulated directly from their
textual form.

Each cycle runs in two phases, which is what makes the result cycle-accurate:

1. **Combinational settle** - every ``comb``/``hw`` operation is evaluated in
   data-dependency order, treating register outputs and input ports as roots.
   Because a hardware body is a graph region, the order is discovered with a
   worklist rather than assumed from the textual order.
2. **Sequential commit** - every register's next value is computed from the
   settled values, and only then are they all written.  Registers therefore all
   sample the same pre-edge state, so ``%reg`` feeding ``comb.add`` feeding
   ``%reg`` counts by one per cycle instead of racing.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple, Union

from mlir.ir import (
    Block,
    BlockArgument,
    ModuleOp,
    Operation,
    OpResult,
    Value,
    Trait,
)
from .hw_dialect import (
    ConstantOp,
