class ConstantFolding(FunctionPass):
    """Fold constant expressions into ``arith.constant`` operations.

    Statistics
    ----------
    ``num_folded``
        Number of operations replaced by a materialised constant.
    ``num_constants_created``
        Number of ``arith.constant`` operations introduced.
    """

    def __init__(self, max_iterations: int = 10) -> None:
        super().__init__()
        self.max_iterations = max_iterations
        self.folder = OperationFolder()
        self._statistics["num_folded"] = 0
        self._statistics["num_constants_created"] = 0

    def run_on_function(self, func: Operation) -> bool:
        rewriter = PatternRewriter()
        changed = False
        for _ in range(max(1, self.max_iterations)):
            self.folder.clear()
            iteration_changed = False
            candidates: List[Operation] = []

            def collect(op: Operation) -> None:
                if op is not func:
                    candidates.append(op)

            func.walk(collect)
            for op in candidates:
                if op.parent is None:
                    continue
                before = self.folder.num_folded
                if self.folder.try_fold(op, rewriter):
                    self.increment_statistic("num_folded", self.folder.num_folded - before)
                    iteration_changed = True
            if not iteration_changed:
                break
            changed = True
        self.set_statistic("num_constants_created", self.folder.num_constants_created)
        return changed


class Canonicalizer(FunctionPass):
    """Run the canonicalisation pattern set to a fixpoint.

    Statistics
    ----------
    ``num_canonicalized``
        Number of successful pattern applications.
    ``num_iterations``
        Number of greedy driver iterations.
    """

    def __init__(self, max_iterations: int = 10) -> None:
        super().__init__()
        self.max_iterations = max_iterations
        self.folder = OperationFolder()
        self._statistics["num_canonicalized"] = 0
        self._statistics["num_iterations"] = 0

    def patterns(self) -> RewritePatternSet:
        return canonicalization_patterns(self.folder)

    def run_on_function(self, func: Operation) -> bool:
        driver = GreedyPatternRewriteDriver(
            self.patterns(), GreedyRewriteConfig(max_iterations=self.max_iterations)
        )
        changed = driver.simplify(func)
        self.increment_statistic("num_canonicalized", driver.num_rewrites)
        self.increment_statistic("num_iterations", driver.num_iterations)
        return changed


class CSEPass(FunctionPass):
    """Common sub-expression elimination for pure operations.

    Statistics
    ----------
    ``num_cse_eliminated``
        Number of redundant operations removed.
    """

    def __init__(self) -> None:
        super().__init__()
        self._statistics["num_cse_eliminated"] = 0

    @staticmethod
    def _key(op: Operation) -> Tuple[Any, ...]:
        return (
            op.name,
            tuple(id(v) for v in op.operands),
            tuple(str(t) for t in op.result_types),
            tuple(sorted((k, str(v)) for k, v in op.attributes.items())),
            tuple(id(b) for b in op.successors),
        )

    def run_on_function(self, func: Operation) -> bool:
        changed = False
        for region in func.regions:
            for block in region.blocks:
                seen: Dict[Tuple[Any, ...], Operation] = {}
                for op in list(block.operations):
                    if not op.is_pure or op.regions or not op.num_results:
                        continue
                    key = self._key(op)
                    existing = seen.get(key)
                    if existing is None:
                        seen[key] = op
                        continue
                    op.replace_all_uses_with(existing.results)
                    op.erase()
                    self.increment_statistic("num_cse_eliminated")
                    changed = True
        return changed


class DCEPass(FunctionPass):
    """Remove pure operations whose results are unused.

    Statistics
    ----------
    ``num_dead_eliminated``
        Number of dead operations removed.
    """

    def __init__(self) -> None:
        super().__init__()
        self._statistics["num_dead_eliminated"] = 0

    def run_on_function(self, func: Operation) -> bool:
        changed = True
        any_change = False
        while changed:
            changed = False
            for region in func.regions:
                for block in region.blocks:
                    for op in reversed(list(block.operations)):
                        if op.is_terminator or op.regions or not op.num_results:
                            continue
                        if not op.is_pure:
                            continue
                        if any(result.has_uses for result in op.results):
                            continue
                        op.erase()
                        self.increment_statistic("num_dead_eliminated")
                        changed = True
                        any_change = True
        return any_change


class SymbolDCEPass(ModulePass):
    """Remove private symbols that nothing references.

    Statistics
    ----------
    ``num_symbols_removed``
    """

    def __init__(self) -> None:
        super().__init__()
        self._statistics["num_symbols_removed"] = 0

    def run_on_module(self, module: Operation) -> bool:
        referenced: Set[str] = set()

        def collect(op: Operation) -> None:
            callee = op.attributes.get("callee")
            if callee is not None:
                referenced.add(str(callee.value))

        module.walk(collect)
        changed = False
        for region in module.regions:
            for block in region.blocks:
                for op in list(block.operations):
                    sym = op.attributes.get("sym_name")
                    visibility = op.attributes.get("sym_visibility")
                    if sym is None or visibility is None:
                        continue
                    if visibility.value != "private" or sym.value in referenced:
                        continue
                    op.erase()
                    self.increment_statistic("num_symbols_removed")
                    changed = True
        return changed


class InlinerPass(ModulePass):
    """Inline single-block callees into their call sites.

    Statistics
    ----------
    ``num_inlined``
    """

    def __init__(self, max_inline_size: int = 50) -> None:
        super().__init__()
        self.max_inline_size = max_inline_size
        self._statistics["num_inlined"] = 0

    def run_on_module(self, module: Operation) -> bool:
        from .ir import SymbolTable

        table = SymbolTable(module)
        calls: List[Operation] = []

        def collect(op: Operation) -> None:
            if op.name in ("func.call", "std.call"):
                calls.append(op)

        module.walk(collect)
        changed = False
        for call in calls:
            callee_attr = call.attributes.get("callee")
            if callee_attr is None:
                continue
            callee = table.lookup(str(callee_attr.value))
            if callee is None or not callee.regions:
                continue
            blocks = callee.regions[0].blocks
            if len(blocks) != 1 or len(blocks[0].operations) > self.max_inline_size:
                continue
            if self._inline_call(call, callee):
                self.increment_statistic("num_inlined")
                changed = True
        return changed

    def _inline_call(self, call: Operation, callee: Operation) -> bool:
        block = call.parent
        if block is None:
            return False
        source = callee.regions[0].blocks[0]
        value_map: Dict[Value, Value] = {}
        for arg, operand in zip(source.arguments, call.operands):
            value_map[arg] = operand
        insert_at = block.operations.index(call)
        returned: List[Value] = []
        for op in source.operations:
            if op.has_trait(Trait.RETURN_LIKE):
                returned = [value_map.get(v, v) for v in op.operands]
                break
            clone = op.clone(value_map)
            block.insert(insert_at, clone)
            insert_at += 1
        if len(returned) != call.num_results:
            return False
        call.replace_all_uses_with(returned)
        call.erase()
        return True


class PrintIRPass(Pass):
    """Diagnostic pass that snapshots the IR into :attr:`snapshots`."""

    def __init__(self, label: str = "") -> None:
        super().__init__()
        self.label = label
        self.snapshots: List[str] = []

    def run_on_operation(self, op: Operation) -> bool:
        from .printer import print_op

        self.snapshots.append(print_op(op))
        self.increment_statistic("num_snapshots")
        return False


# ---------------------------------------------------------------------------
# Pass manager
# ---------------------------------------------------------------------------


class PassManager:
    """Runs an ordered pipeline of passes over an operation."""

    def __init__(
        self,
        op_name: Optional[str] = None,
        verify_each: bool = False,
        analysis_manager: Optional[AnalysisManager] = None,
    ) -> None:
        self.op_name = op_name
        self.verify_each = verify_each
        self.analysis_manager = (
            analysis_manager if analysis_manager is not None else AnalysisManager()
        )
        self._passes: List[Pass] = []
        self._nested: List["PassManager"] = []
        self._run_log: List[Tuple[str, bool]] = []

    # -- pipeline construction -------------------------------------------
    def add_pass(self, pass_instance: Pass) -> "PassManager":
        self._passes.append(pass_instance)
        return self

    def add_passes(self, passes: Sequence[Pass]) -> "PassManager":
        for item in passes:
            self.add_pass(item)
        return self

    def nest(self, op_name: str) -> "PassManager":
        nested = PassManager(
            op_name=op_name,
            verify_each=self.verify_each,
            analysis_manager=self.analysis_manager,
        )
        self._nested.append(nested)
        self._passes.append(_NestedPipeline(nested))
        return nested

    #: Alias matching the older spelling.
    def nest_pass_manager(self, op_name: Optional[str] = None) -> "PassManager":
        return self.nest(op_name) if op_name else PassManager(
            analysis_manager=self.analysis_manager
        )

    @property
    def passes(self) -> List[Pass]:
        return list(self._passes)

    def __len__(self) -> int:
        return len(self._passes)

    # -- execution --------------------------------------------------------
    def run(self, op: Operation) -> bool:
        changed = False
        self._run_log.clear()
        targets = self._targets(op)
        for pass_instance in self._passes:
            pass_changed = False
            for target in targets:
                if pass_instance.run_on_operation(target):
                    pass_changed = True
            self._run_log.append((pass_instance.name, pass_changed))
            if pass_changed:
                self.analysis_manager.invalidate_all()
                changed = True
            if self.verify_each:
                errors = Verifier.verify(op)
                if errors:
                    raise VerificationError(
                        f"IR failed to verify after '{pass_instance.name}': "
                        + "; ".join(errors)
                    )
        return changed

    def _targets(self, op: Operation) -> List[Operation]:
        if self.op_name is None:
            return [op]
        found: List[Operation] = []

        def collect(candidate: Operation) -> None:
            if candidate.name == self.op_name:
                found.append(candidate)

        op.walk(collect)
        return found

    # -- reporting --------------------------------------------------------
    @property
    def statistics(self) -> Dict[str, Dict[str, int]]:
        stats: Dict[str, Dict[str, int]] = {}
        for pass_instance in self._passes:
            if isinstance(pass_instance, _NestedPipeline):
                stats.update(pass_instance.pipeline.statistics)
                continue
            stats[pass_instance.name] = pass_instance.statistics
        return stats

    @property
    def run_log(self) -> List[Tuple[str, bool]]:
        return list(self._run_log)

    def pipeline_description(self) -> str:
        parts: List[str] = []
        for pass_instance in self._passes:
            if isinstance(pass_instance, _NestedPipeline):
                nested = pass_instance.pipeline
                parts.append(f"{nested.op_name}({nested.pipeline_description()})")
            else:
                parts.append(pass_instance.argument)
        return ",".join(parts)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<PassManager {self.pipeline_description()!r}>"


class _NestedPipeline(Pass):
    """Adapter that lets a nested :class:`PassManager` sit in a pipeline."""

    def __init__(self, pipeline: PassManager) -> None:
        super().__init__()
        self.pipeline = pipeline

    @property
    def name(self) -> str:
        return f"nested[{self.pipeline.op_name}]"

    def run_on_operation(self, op: Operation) -> bool:
        return self.pipeline.run(op)

