        self.op = op
        self.entries: Dict[str, SymbolEntry] = {}
        self.children: List["Scope"] = []
        if parent is not None:
            parent.children.append(self)

    # -- definitions ------------------------------------------------------
    def define(self, entry: SymbolEntry) -> SymbolEntry:
        entry.scope_name = self.name
        self.entries[entry.name] = entry
        return entry

    def lookup_local(self, name: str) -> Optional[SymbolEntry]:
        return self.entries.get(name.lstrip("@%"))

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        """Search this scope then every enclosing one."""
        scope: Optional[Scope] = self
        key = name.lstrip("@%")
        while scope is not None:
            found = scope.entries.get(key)
            if found is not None:
                return found
            scope = scope.parent
        return None

    def find_child(self, name: str) -> Optional["Scope"]:
        for child in self.children:
            if child.name == name:
                return child
        return None

    # -- queries ----------------------------------------------------------
    def names(self) -> List[str]:
        return sorted(self.entries)

    @property
    def depth(self) -> int:
        return 0 if self.parent is None else self.parent.depth + 1

    def walk(self) -> Iterator["Scope"]:
        yield self
        for child in self.children:
            yield from child.walk()

    def __len__(self) -> int:
        return len(self.entries)

    def __contains__(self, name: str) -> bool:
        return self.lookup(name) is not None

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Scope {self.name!r} entries={len(self.entries)} children={len(self.children)}>"


@dataclass
class SymbolResolution:
    """The result of running :class:`SymbolResolver`."""

    root_scope: Scope
    definitions: Dict[str, SymbolEntry] = field(default_factory=dict)
    references: List[SymbolReference] = field(default_factory=list)
    values: Dict[str, SymbolEntry] = field(default_factory=dict)
    errors: List[str] = field(default_factory=list)

    # -- counts -----------------------------------------------------------
    @property
    def num_resolved(self) -> int:
        """How many symbol definitions were bound into the scope tree."""
        return len(self.definitions)

    @property
    def num_references(self) -> int:
        return len(self.references)

    @property
    def num_references_resolved(self) -> int:
        return sum(1 for ref in self.references if ref.is_resolved)

    @property
    def unresolved(self) -> List[SymbolReference]:
        return [ref for ref in self.references if not ref.is_resolved]

    @property
    def is_complete(self) -> bool:
        return not self.unresolved and not self.errors

    # -- lookup -----------------------------------------------------------
    def names(self) -> List[str]:
        return sorted(self.definitions)

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        key = name.lstrip("@%")
        return self.definitions.get(key) or self.root_scope.lookup(key)

    def operation(self, name: str) -> Optional[Operation]:
        entry = self.lookup(name)
        return entry.op if entry is not None else None

    def scope_for(self, name: str) -> Optional[Scope]:
        return self.root_scope.find_child(name.lstrip("@%"))

    def __len__(self) -> int:
        return len(self.definitions)

    def __contains__(self, name: str) -> bool:
        return self.lookup(name) is not None

    def to_text(self) -> str:
        lines: List[str] = []
        for scope in self.root_scope.walk():
            indent = "  " * scope.depth
            lines.append(f"{indent}{scope.name}:")
            for name in scope.names():
                lines.append(f"{indent}  {scope.entries[name]}")
        for ref in self.references:
            lines.append(str(ref))
        return "\n".join(lines)


class SymbolResolver:
    """Builds the scope tree for an operation and binds every reference."""

    def __init__(self, root: Operation) -> None:
        self.root = root
        self._resolution: Optional[SymbolResolution] = None

    # -- entry point ------------------------------------------------------
    def resolve(self) -> SymbolResolution:
        """Run the analysis (cached: repeated calls return the same result)."""
        if self._resolution is not None:
            return self._resolution

        root_name = SymbolTable.get_symbol_name(self.root) or self._default_root_name()
        root_scope = Scope(root_name, op=self.root)
        resolution = SymbolResolution(root_scope=root_scope)

        self._collect_definitions(self.root, root_scope, resolution)
        self._collect_references(self.root, resolution)
        self._bind_references(resolution)

        self._resolution = resolution
        return resolution

    def _default_root_name(self) -> str:
        return "module" if self.root.name == "builtin.module" else self.root.name

    # -- definitions ------------------------------------------------------
    def _collect_definitions(
        self, op: Operation, scope: Scope, resolution: SymbolResolution
    ) -> None:
        for region in op.regions:
            for block in region.blocks:
                self._collect_block(block, scope, resolution)

    def _collect_block(
        self, block: Block, scope: Scope, resolution: SymbolResolution
    ) -> None:
        if block.label:
            scope.define(SymbolEntry(block.label, SymbolKind.BLOCK))
        for child in block.operations:
            symbol = SymbolTable.get_symbol_name(child)
            if symbol is not None:
                entry = scope.define(
                    SymbolEntry(
                        symbol,
                        SymbolKind.for_operation(child),
                        op=child,
                        type=self._declared_type(child),
                    )
                )
                if entry.is_symbol_definition:
                    resolution.definitions[symbol] = entry
                nested = Scope(symbol, parent=scope, op=child)
                self._collect_arguments(child, nested, resolution)
                self._collect_definitions(child, nested, resolution)
                continue

            self._record_results(child, scope, resolution)
            # Operations without a symbol still own regions (``sv.if``,
            # ``fsm.state``); their bodies share the enclosing scope.
            self._collect_definitions(child, scope, resolution)

    def _collect_arguments(
        self, op: Operation, scope: Scope, resolution: SymbolResolution
    ) -> None:
        kind = (
            SymbolKind.PORT
            if op.name in ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")
            else SymbolKind.ARGUMENT
        )
        for region in op.regions:
            for block in region.blocks:
                for index, argument in enumerate(block.arguments):
                    name = argument.name or f"arg{index}"
                    entry = scope.define(
                        SymbolEntry(name, kind, op=op, value=argument, type=argument.type)
                    )
                    resolution.values[entry.qualified_name] = entry

    def _record_results(
        self, op: Operation, scope: Scope, resolution: SymbolResolution
    ) -> None:
        stateful = op.name.startswith("seq.") or op.name in ("firrtl.reg", "sv.reg")
        kind = SymbolKind.REGISTER if stateful else SymbolKind.VALUE
        for result in op.results:
            if not result.name:
                continue
            entry = scope.define(
                SymbolEntry(result.name, kind, op=op, value=result, type=result.type)
            )
            resolution.values[entry.qualified_name] = entry

    @staticmethod
    def _declared_type(op: Operation) -> Optional[Type]:
        attr = op.attributes.get("function_type")
        return attr.value if attr is not None else None

    # -- references -------------------------------------------------------
    def _collect_references(
        self, op: Operation, resolution: SymbolResolution
    ) -> None:
        def visit(candidate: Operation) -> None:
            for name in REFERENCE_ATTRIBUTES:
                attr = candidate.attributes.get(name)
                symbol = self._symbol_of(attr)
                if symbol is None:
                    continue
                resolution.references.append(
                    SymbolReference(symbol, candidate, attribute=name)
                )

        op.walk(visit)

    @staticmethod
    def _symbol_of(attr: Optional[Attribute]) -> Optional[str]:
        if isinstance(attr, FlatSymbolRefAttr):
            return str(attr.value)
        if isinstance(attr, StringAttr):
            return attr.value.lstrip("@")
        return None

    def _bind_references(self, resolution: SymbolResolution) -> None:
        for ref in resolution.references:
            entry = resolution.lookup(ref.name)
            if entry is None:
                resolution.errors.append(
                    f"unresolved symbol reference @{ref.name} in '{ref.user.name}'"
                )
                continue
            ref.target = entry.op

    # -- shorthand --------------------------------------------------------
    @property
    def resolution(self) -> SymbolResolution:
        return self.resolve()

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        return self.resolve().lookup(name)

    def names(self) -> List[str]:
        return self.resolve().names()

    @property
    def num_resolved(self) -> int:
        return self.resolve().num_resolved

    def __len__(self) -> int:
        return len(self.resolve())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<SymbolResolver root={self.root.name!r}>"


def resolve_symbols(root: Operation) -> SymbolResolution:
    """Convenience wrapper: ``resolve_symbols(module).num_resolved``."""
    return SymbolResolver(root).resolve()

input.content:
"""Type (sort) analysis for the semantic layer.

K assigns every term a *sort*; the circuit semantics needs the same information
for a different reason - a rule cannot compute ``comb.add`` without knowing the
width to wrap the result to.  This module derives, for every SSA value in a
module, both

* the MLIR :class:`~src.mlir.ir.Type` it carries, and
* the coarse :class:`Sort` the semantics dispatches on (integer, clock, reset,
  aggregate, ...) together with its bit width.

Types come from the parsed IR where the source spells them out, and are
otherwise *inferred* from the operands: ``comb.mux`` takes its width from its
data inputs, ``comb.icmp`` always produces one bit, ``comb.concat`` sums its
operand widths.  Inference iterates to a fixed point so graph regions - where a
value may be used above its definition, as in ``inputs/counter.mlir`` - resolve.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Sequence, Tuple

from mlir.ir import (
    BlockArgument,
    FunctionType,
    IndexType,
    IntegerType,
    ModuleOp,
    OpResult,
    OpaqueType,
    Operation,
    Type,
    TypeAttr,
    Value,
)

from .symbols import SymbolResolver, SymbolResolution

__all__ = [
    "Sort",
    "TypeBinding",
    "TypeConflict",
    "TypeEnvironment",
    "TypeResolution",
    "TypeResolver",
    "resolve_types",
    "sort_of",
    "width_of",
]


class Sort(Enum):
    """The coarse semantic sort a rule dispatches on."""

    INT = "Int"
    BOOL = "Bool"
    CLOCK = "Clock"
    RESET = "Reset"
    INDEX = "Index"
    FLOAT = "Float"
    ARRAY = "Array"
    STRUCT = "Struct"
    FUNCTION = "Function"
    NONE = "None"
    UNKNOWN = "Unknown"


#: ``!seq.clock`` and the FIRRTL clock spellings.
_CLOCK_MNEMONICS = frozenset({"clock"})
_RESET_MNEMONICS = frozenset({"reset", "asyncreset"})


def sort_of(type: Optional[Type]) -> Sort:
    """Classify an MLIR type into a semantic :class:`Sort`."""
    if type is None:
        return Sort.UNKNOWN
    if isinstance(type, IntegerType):
        return Sort.BOOL if type.width == 1 else Sort.INT
    if isinstance(type, IndexType):
        return Sort.INDEX
    if isinstance(type, FunctionType):
        return Sort.FUNCTION
    if isinstance(type, OpaqueType):
        if type.mnemonic in _CLOCK_MNEMONICS:
            return Sort.CLOCK
        if type.mnemonic in _RESET_MNEMONICS:
            return Sort.RESET
        if type.mnemonic in ("array", "vector"):
            return Sort.ARRAY
        if type.mnemonic in ("struct", "bundle"):
            return Sort.STRUCT
        if type.mnemonic in ("uint", "sint"):
            return Sort.INT
        return Sort.UNKNOWN
    mnemonic = getattr(type, "mnemonic", "")
    if mnemonic in ("f16", "f32", "f64", "bf16"):
        return Sort.FLOAT
    text = str(type)
    if text.startswith("!hw.array") or text.startswith("!firrtl.vector"):
        return Sort.ARRAY
    if text.startswith("!hw.struct") or text.startswith("!firrtl.bundle"):
        return Sort.STRUCT
    if text == "none":
        return Sort.NONE
    if type.bitwidth():
        return Sort.INT
    return Sort.UNKNOWN


def width_of(type: Optional[Type]) -> int:
    """Bit width of ``type``, or ``0`` when it has none.

    Delegates to the hardware dialect so ``!seq.clock`` and ``!hw.array<4xi8>``
    report the widths the CIRCT layer already agreed on.
    """
    if type is None:
        return 0
    from circt.hw_dialect import bit_width_of

    return bit_width_of(type)


@dataclass
class TypeBinding:
    """One value's resolved type."""

    key: str
    type: Optional[Type]
    sort: Sort = Sort.UNKNOWN
    width: int = 0
    value: Optional[Value] = None
    op: Optional[Operation] = None
    inferred: bool = False

    @property
    def is_resolved(self) -> bool:
        return self.type is not None and self.sort is not Sort.UNKNOWN

    def __str__(self) -> str:
        origin = "inferred" if self.inferred else "declared"
        return f"{self.key} : {self.type} [{self.sort.value}/{self.width}, {origin}]"


@dataclass
class TypeConflict:
    """Two incompatible types were derived for the same value."""

    key: str
    expected: Optional[Type]
    actual: Optional[Type]
    op: Optional[Operation] = None

    def __str__(self) -> str:
        where = f" at '{self.op.name}'" if self.op is not None else ""
        return f"type conflict for {self.key}: {self.expected} vs {self.actual}{where}"


class TypeEnvironment:
    """A mutable map from SSA values (and their names) to types."""

    def __init__(self) -> None:
        self._by_value: Dict[int, TypeBinding] = {}
        self._by_name: Dict[str, TypeBinding] = {}

    # -- mutation ---------------------------------------------------------
    def bind(self, binding: TypeBinding) -> TypeBinding:
        if binding.value is not None:
            self._by_value[id(binding.value)] = binding
        if binding.key:
            self._by_name[binding.key] = binding
        return binding

    # -- lookup -----------------------------------------------------------
    def lookup_value(self, value: Value) -> Optional[TypeBinding]:
        found = self._by_value.get(id(value))
        if found is not None:
            return found
        name = getattr(value, "name", None)
        return self._by_name.get(name) if name else None

    def lookup(self, key: Any) -> Optional[TypeBinding]:
        if isinstance(key, Value):
            return self.lookup_value(key)
        if isinstance(key, str):
            direct = self._by_name.get(key)
            if direct is not None:
                return direct
            # Accept both ``name`` and ``scope::name``.
            suffix = "::" + key
            for stored, binding in self._by_name.items():
                if stored.endswith(suffix):
                    return binding
        return None

    def type_of(self, key: Any) -> Optional[Type]:
        binding = self.lookup(key)
        return binding.type if binding is not None else None

    def width(self, key: Any) -> int:
        binding = self.lookup(key)
        return binding.width if binding is not None else 0

    def sort(self, key: Any) -> Sort:
        binding = self.lookup(key)
        return binding.sort if binding is not None else Sort.UNKNOWN

    # -- views -------------------------------------------------------------
    @property
    def bindings(self) -> List[TypeBinding]:
        seen: Dict[int, TypeBinding] = {}
        for binding in list(self._by_value.values()) + list(self._by_name.values()):
            seen[id(binding)] = binding
        return list(seen.values())

    def names(self) -> List[str]:
        return sorted(self._by_name)

    def __len__(self) -> int:
        return len(self.bindings)

    def __contains__(self, key: Any) -> bool:
        return self.lookup(key) is not None


@dataclass
class TypeResolution:
    """The result of running :class:`TypeResolver`."""

    environment: TypeEnvironment = field(default_factory=TypeEnvironment)
    conflicts: List[TypeConflict] = field(default_factory=list)
    signatures: Dict[str, FunctionType] = field(default_factory=dict)
    iterations: int = 0

    # -- counts -----------------------------------------------------------
    @property
    def num_typed(self) -> int:
        return sum(1 for b in self.environment.bindings if b.is_resolved)

    @property
    def num_inferred(self) -> int:
        return sum(1 for b in self.environment.bindings if b.inferred and b.is_resolved)

    @property
    def unresolved(self) -> List[TypeBinding]:
        return [b for b in self.environment.bindings if not b.is_resolved]

    @property
    def is_consistent(self) -> bool:
        return not self.conflicts

    @property
    def is_complete(self) -> bool:
        return not self.conflicts and not self.unresolved

    # -- lookup -----------------------------------------------------------
    def type_of(self, key: Any) -> Optional[Type]:
        return self.environment.type_of(key)

    def sort_of(self, key: Any) -> Sort:
        return self.environment.sort(key)

    def width_of(self, key: Any) -> int:
        return self.environment.width(key)

    def signature(self, symbol: str) -> Optional[FunctionType]:
        return self.signatures.get(symbol.lstrip("@"))

    def return_type(self, symbol: str) -> Optional[Type]:
        """The single result type of ``symbol``, or ``None``."""
        signature = self.signature(symbol)
        if signature is None or not signature.results:
            return None
        return signature.results[0]

    def result_types(self, symbol: str) -> List[Type]:
        signature = self.signature(symbol)
        return list(signature.results) if signature is not None else []

    def argument_types(self, symbol: str) -> List[Type]:
        signature = self.signature(symbol)
        return list(signature.inputs) if signature is not None else []

    def to_text(self) -> str:
        lines = [str(b) for b in sorted(self.environment.bindings, key=lambda b: b.key)]
        lines.extend(str(c) for c in self.conflicts)
        return "\n".join(lines)

    def __len__(self) -> int:
        return len(self.environment)


#: Operations whose result is always a single bit regardless of operand width.
SINGLE_BIT_RESULT_OPS = frozenset(
    {"comb.icmp", "comb.parity", "arith.cmpi", "arith.cmpf", "seq.from_clock"}
)

#: Operations whose result width is the sum of the operand widths.
SUMMED_WIDTH_OPS = frozenset({"comb.concat"})

#: Operations that forward the type of a specific operand.
_FORWARDED_OPERAND = {
    "comb.mux": 1,
    "hw.wire": 0,
    "seq.compreg": 0,
    "seq.compreg.ce": 0,
    "seq.firreg": 0,
    "firrtl.node": 0,
    "arith.select": 1,
}


class TypeResolver:
    """Derives a type and a :class:`Sort` for every value in an operation tree."""

    #: Safety net for the fixed-point loop.
    MAX_ITERATIONS = 8

    def __init__(
        self,
        root: Operation,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        self.symbols = symbols if symbols is not None else SymbolResolver(root).resolve()
        self._resolution: Optional[TypeResolution] = None

    # -- entry point ------------------------------------------------------
    def resolve(self) -> TypeResolution:
        """Run the analysis (cached: repeated calls return the same result)."""
        if self._resolution is not None:
            return self._resolution

        resolution = TypeResolution()
        self._collect_signatures(resolution)
        self._seed_declared_types(resolution)

        for iteration in range(1, self.MAX_ITERATIONS + 1):
            resolution.iterations = iteration
            if not self._infer_once(resolution):
                break

        self._resolution = resolution
        return resolution

    # -- signatures -------------------------------------------------------
    def _collect_signatures(self, resolution: TypeResolution) -> None:
        for name, entry in self.symbols.definitions.items():
            op = entry.op
            if op is None:
                continue
            attr = op.attributes.get("function_type")
            if isinstance(attr, TypeAttr) and isinstance(attr.value, FunctionType):
                resolution.signatures[name] = attr.value

    # -- declared types ---------------------------------------------------
    def _seed_declared_types(self, resolution: TypeResolution) -> None:
        env = resolution.environment

        def visit(op: Operation) -> None:
            scope = self._scope_name(op)
            for region in op.regions:
                for block in region.blocks:
                    for index, argument in enumerate(block.arguments):
                        name = argument.name or f"arg{index}"
                        self._bind(env, scope, name, argument.type, argument, op, False)
            for result in op.results:
                if not result.name:
                    continue
                self._bind(env, scope, result.name, result.type, result, op, False)

        self.root.walk(visit)

    def _scope_name(self, op: Operation) -> str:
        """The name of the symbol-carrying ancestor (or the op itself)."""
        from mlir.ir import SymbolTable

        current: Optional[Operation] = op
        while current is not None:
            symbol = SymbolTable.get_symbol_name(current)
            if symbol is not None and current.name != "builtin.module":
                return symbol
            current = current.parent_op
        return self.symbols.root_scope.name

    def _bind(
        self,
        env: TypeEnvironment,
        scope: str,
        name: str,
        type: Optional[Type],
        value: Optional[Value],
        op: Optional[Operation],
        inferred: bool,
    ) -> TypeBinding:
        key = f"{scope}::{name}" if scope else name
        binding = TypeBinding(
            key=key,
            type=type,
            sort=sort_of(type),
            width=width_of(type),
            value=value,
            op=op,
            inferred=inferred,
        )
        return env.bind(binding)

    # -- inference --------------------------------------------------------
    def _infer_once(self, resolution: TypeResolution) -> bool:
        """One inference sweep.  Returns ``True`` when something changed."""
        env = resolution.environment
        changed = False

        def visit(op: Operation) -> None:
            nonlocal changed
            for result in op.results:
                binding = env.lookup_value(result)
                if binding is not None and binding.is_resolved:
                    continue
                inferred = self.infer_result_type(op, result, env)
                if inferred is None:
                    continue
                scope = self._scope_name(op)
                name = result.name or f"{op.mnemonic}{result.index}"
                previous = binding.type if binding is not None else None
                if previous is not None and previous != inferred:
                    resolution.conflicts.append(
                        TypeConflict(name, previous, inferred, op)
                    )
                    continue
                self._bind(env, scope, name, inferred, result, op, True)
                # Keep the IR and the analysis in agreement.
                result.type = inferred
                changed = True

        self.root.walk(visit)
        return changed

    def infer_result_type(
        self,
        op: Operation,
        result: OpResult,
        env: Optional[TypeEnvironment] = None,
    ) -> Optional[Type]:
        """Infer the type of ``result`` from ``op``'s operands and attributes."""
        env = env if env is not None else TypeEnvironment()

        if op.name in SINGLE_BIT_RESULT_OPS:
            return IntegerType(1)

        value_attr = op.attributes.get("value")
        declared = getattr(value_attr, "type", None)
        if declared is not None:
            return declared

        operand_types = [self._operand_type(operand, env) for operand in op.operands]
        known = [t for t in operand_types if t is not None]

        if op.name in SUMMED_WIDTH_OPS:
            widths = [width_of(t) for t in known]
            if widths and all(widths):
                return IntegerType(sum(widths))
            return None

        index = _FORWARDED_OPERAND.get(op.name)
        if index is not None and index < len(operand_types):
            return operand_types[index]

        # The general rule: same-typed operands give a same-typed result, which
        # covers every ``comb``/``arith`` binary operation.
        for candidate in known:
            if sort_of(candidate) in (Sort.INT, Sort.BOOL):
                return candidate
        return known[0] if known else None

    def _operand_type(
        self, operand: Any, env: TypeEnvironment
    ) -> Optional[Type]:
        if isinstance(operand, Value):
            binding = env.lookup_value(operand)
            if binding is not None and binding.type is not None:
                return binding.type
            return operand.type
        binding = env.lookup(operand)
        return binding.type if binding is not None else None

    # -- shorthand --------------------------------------------------------
    @property
    def resolution(self) -> TypeResolution:
        return self.resolve()

    @property
    def environment(self) -> TypeEnvironment:
        return self.resolve().environment

    def type_of(self, key: Any) -> Optional[Type]:
        return self.resolve().type_of(key)

    def sort_of(self, key: Any) -> Sort:
        return self.resolve().sort_of(key)

    def width_of(self, key: Any) -> int:
        return self.resolve().width_of(key)

    def signature(self, symbol: str) -> Optional[FunctionType]:
        return self.resolve().signature(symbol)

    def return_type(self, symbol: str) -> Optional[Type]:
        """The declared result type of a function-like symbol."""
        return self.resolve().return_type(symbol)

    #: Spelled out for readers coming from the K side of the stack.
    resolve_return_type = return_type

    def result_type_name(self, symbol: str) -> str:
        """``str`` of the symbol's result type, e.g. ``"i32"``."""
        result = self.return_type(symbol)
        return str(result) if result is not None else ""

    @property
    def num_typed(self) -> int:
        return self.resolve().num_typed

    def __len__(self) -> int:
        return len(self.resolve())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<TypeResolver root={self.root.name!r}>"


def resolve_types(
    root: Operation, symbols: Optional[SymbolResolution] = None
) -> TypeResolution:
    """Convenience wrapper: ``resolve_types(module).return_type("f")``."""
    return TypeResolver(root, symbols).resolve()

toolUseResult.content:
"""Type (sort) analysis for the semantic layer.

K assigns every term a *sort*; the circuit semantics needs the same information
for a different reason - a rule cannot compute ``comb.add`` without knowing the
width to wrap the result to.  This module derives, for every SSA value in a
module, both

* the MLIR :class:`~src.mlir.ir.Type` it carries, and
* the coarse :class:`Sort` the semantics dispatches on (integer, clock, reset,
  aggregate, ...) together with its bit width.

Types come from the parsed IR where the source spells them out, and are
otherwise *inferred* from the operands: ``comb.mux`` takes its width from its
data inputs, ``comb.icmp`` always produces one bit, ``comb.concat`` sums its
operand widths.  Inference iterates to a fixed point so graph regions - where a
value may be used above its definition, as in ``inputs/counter.mlir`` - resolve.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Sequence, Tuple

from mlir.ir import (
    BlockArgument,
    FunctionType,
    IndexType,
    IntegerType,
    ModuleOp,
    OpResult,
    OpaqueType,
    Operation,
    Type,
    TypeAttr,
    Value,
)

from .symbols import SymbolResolver, SymbolResolution

__all__ = [
    "Sort",
    "TypeBinding",
    "TypeConflict",
    "TypeEnvironment",
    "TypeResolution",
    "TypeResolver",
    "resolve_types",
    "sort_of",
    "width_of",
]


class Sort(Enum):
    """The coarse semantic sort a rule dispatches on."""

    INT = "Int"
    BOOL = "Bool"
    CLOCK = "Clock"
    RESET = "Reset"
    INDEX = "Index"
    FLOAT = "Float"
    ARRAY = "Array"
    STRUCT = "Struct"
    FUNCTION = "Function"
    NONE = "None"
    UNKNOWN = "Unknown"


#: ``!seq.clock`` and the FIRRTL clock spellings.
_CLOCK_MNEMONICS = frozenset({"clock"})
_RESET_MNEMONICS = frozenset({"reset", "asyncreset"})


def sort_of(type: Optional[Type]) -> Sort:
    """Classify an MLIR type into a semantic :class:`Sort`."""
    if type is None:
        return Sort.UNKNOWN
    if isinstance(type, IntegerType):
        return Sort.BOOL if type.width == 1 else Sort.INT
    if isinstance(type, IndexType):
        return Sort.INDEX
    if isinstance(type, FunctionType):
        return Sort.FUNCTION
    if isinstance(type, OpaqueType):
        if type.mnemonic in _CLOCK_MNEMONICS:
            return Sort.CLOCK
        if type.mnemonic in _RESET_MNEMONICS:
            return Sort.RESET
        if type.mnemonic in ("array", "vector"):
            return Sort.ARRAY
        if type.mnemonic in ("struct", "bundle"):
            return Sort.STRUCT
        if type.mnemonic in ("uint", "sint"):
            return Sort.INT
        return Sort.UNKNOWN
    mnemonic = getattr(type, "mnemonic", "")
    if mnemonic in ("f16", "f32", "f64", "bf16"):
        return Sort.FLOAT
    text = str(type)
    if text.startswith("!hw.array") or text.startswith("!firrtl.vector"):
        return Sort.ARRAY
    if text.startswith("!hw.struct") or text.startswith("!firrtl.bundle"):
        return Sort.STRUCT
    if text == "none":
        return Sort.NONE
    if type.bitwidth():
        return Sort.INT
    return Sort.UNKNOWN


def width_of(type: Optional[Type]) -> int:
    """Bit width of ``type``, or ``0`` when it has none.

    Delegates to the hardware dialect so ``!seq.clock`` and ``!hw.array<4xi8>``
    report the widths the CIRCT layer already agreed on.
    """
    if type is None:
        return 0
    from circt.hw_dialect import bit_width_of

    return bit_width_of(type)


@dataclass
class TypeBinding:
    """One value's resolved type."""

    key: str
    type: Optional[Type]
    sort: Sort = Sort.UNKNOWN
    width: int = 0
    value: Optional[Value] = None
    op: Optional[Operation] = None
    inferred: bool = False

    @property
    def is_resolved(self) -> bool:
        return self.type is not None and self.sort is not Sort.UNKNOWN

    def __str__(self) -> str:
        origin = "inferred" if self.inferred else "declared"
        return f"{self.key} : {self.type} [{self.sort.value}/{self.width}, {origin}]"


@dataclass
class TypeConflict:
    """Two incompatible types were derived for the same value."""

    key: str
    expected: Optional[Type]
    actual: Optional[Type]
    op: Optional[Operation] = None

    def __str__(self) -> str:
        where = f" at '{self.op.name}'" if self.op is not None else ""
        return f"type conflict for {self.key}: {self.expected} vs {self.actual}{where}"


class TypeEnvironment:
    """A mutable map from SSA values (and their names) to types."""

    def __init__(self) -> None:
        self._by_value: Dict[int, TypeBinding] = {}
        self._by_name: Dict[str, TypeBinding] = {}

    # -- mutation ---------------------------------------------------------
    def bind(self, binding: TypeBinding) -> TypeBinding:
        if binding.value is not None:
            self._by_value[id(binding.value)] = binding
        if binding.key:
            self._by_name[binding.key] = binding
        return binding

    # -- lookup -----------------------------------------------------------
    def lookup_value(self, value: Value) -> Optional[TypeBinding]:
        found = self._by_value.get(id(value))
        if found is not None:
            return found
        name = getattr(value, "name", None)
        return self._by_name.get(name) if name else None

    def lookup(self, key: Any) -> Optional[TypeBinding]:
        if isinstance(key, Value):
            return self.lookup_value(key)
        if isinstance(key, str):
            direct = self._by_name.get(key)
            if direct is not None:
                return direct
            # Accept both ``name`` and ``scope::name``.
            suffix = "::" + key
            for stored, binding in self._by_name.items():
                if stored.endswith(suffix):
                    return binding
        return None

    def type_of(self, key: Any) -> Optional[Type]:
        binding = self.lookup(key)
        return binding.type if binding is not None else None

    def width(self, key: Any) -> int:
        binding = self.lookup(key)
        return binding.width if binding is not None else 0

    def sort(self, key: Any) -> Sort:
        binding = self.lookup(key)
        return binding.sort if binding is not None else Sort.UNKNOWN

    # -- views -------------------------------------------------------------
    @property
    def bindings(self) -> List[TypeBinding]:
        seen: Dict[int, TypeBinding] = {}
        for binding in list(self._by_value.values()) + list(self._by_name.values()):
            seen[id(binding)] = binding
        return list(seen.values())

    def names(self) -> List[str]:
        return sorted(self._by_name)

    def __len__(self) -> int:
        return len(self.bindings)

    def __contains__(self, key: Any) -> bool:
        return self.lookup(key) is not None


@dataclass
class TypeResolution:
    """The result of running :class:`TypeResolver`."""

    environment: TypeEnvironment = field(default_factory=TypeEnvironment)
    conflicts: List[TypeConflict] = field(default_factory=list)
    signatures: Dict[str, FunctionType] = field(default_factory=dict)
    iterations: int = 0

    # -- counts -----------------------------------------------------------
    @property
    def num_typed(self) -> int:
        return sum(1 for b in self.environment.bindings if b.is_resolved)

    @property
    def num_inferred(self) -> int:
        return sum(1 for b in self.environment.bindings if b.inferred and b.is_resolved)

    @property
    def unresolved(self) -> List[TypeBinding]:
        return [b for b in self.environment.bindings if not b.is_resolved]

    @property
    def is_consistent(self) -> bool:
        return not self.conflicts

    @property
    def is_complete(self) -> bool:
        return not self.conflicts and not self.unresolved

    # -- lookup -----------------------------------------------------------
    def type_of(self, key: Any) -> Optional[Type]:
        return self.environment.type_of(key)

    def sort_of(self, key: Any) -> Sort:
        return self.environment.sort(key)

    def width_of(self, key: Any) -> int:
        return self.environment.width(key)

    def signature(self, symbol: str) -> Optional[FunctionType]:
        return self.signatures.get(symbol.lstrip("@"))

    def return_type(self, symbol: str) -> Optional[Type]:
        """The single result type of ``symbol``, or ``None``."""
        signature = self.signature(symbol)
        if signature is None or not signature.results:
            return None
        return signature.results[0]

    def result_types(self, symbol: str) -> List[Type]:
        signature = self.signature(symbol)
        return list(signature.results) if signature is not None else []

    def argument_types(self, symbol: str) -> List[Type]:
        signature = self.signature(symbol)
        return list(signature.inputs) if signature is not None else []

    def to_text(self) -> str:
        lines = [str(b) for b in sorted(self.environment.bindings, key=lambda b: b.key)]
        lines.extend(str(c) for c in self.conflicts)
        return "\n".join(lines)

    def __len__(self) -> int:
        return len(self.environment)


#: Operations whose result is always a single bit regardless of operand width.
SINGLE_BIT_RESULT_OPS = frozenset(
    {"comb.icmp", "comb.parity", "arith.cmpi", "arith.cmpf", "seq.from_clock"}
)

#: Operations whose result width is the sum of the operand widths.
SUMMED_WIDTH_OPS = frozenset({"comb.concat"})

#: Operations that forward the type of a specific operand.
_FORWARDED_OPERAND = {
    "comb.mux": 1,
    "hw.wire": 0,
    "seq.compreg": 0,
    "seq.compreg.ce": 0,
    "seq.firreg": 0,
    "firrtl.node": 0,
    "arith.select": 1,
}


class TypeResolver:
    """Derives a type and a :class:`Sort` for every value in an operation tree."""

    #: Safety net for the fixed-point loop.
    MAX_ITERATIONS = 8

    def __init__(
        self,
        root: Operation,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        self.symbols = symbols if symbols is not None else SymbolResolver(root).resolve()
        self._resolution: Optional[TypeResolution] = None

    # -- entry point ------------------------------------------------------
    def resolve(self) -> TypeResolution:
        """Run the analysis (cached: repeated calls return the same result)."""
        if self._resolution is not None:
            return self._resolution

        resolution = TypeResolution()
        self._collect_signatures(resolution)
        self._seed_declared_types(resolution)

        for iteration in range(1, self.MAX_ITERATIONS + 1):
            resolution.iterations = iteration
            if not self._infer_once(resolution):
                break

        self._resolution = resolution
        return resolution

    # -- signatures -------------------------------------------------------
    def _collect_signatures(self, resolution: TypeResolution) -> None:
        for name, entry in self.symbols.definitions.items():
            op = entry.op
            if op is None:
                continue
            attr = op.attributes.get("function_type")
            if isinstance(attr, TypeAttr) and isinstance(attr.value, FunctionType):
                resolution.signatures[name] = attr.value

    # -- declared types ---------------------------------------------------
    def _seed_declared_types(self, resolution: TypeResolution) -> None:
        env = resolution.environment

        def visit(op: Operation) -> None:
            scope = self._scope_name(op)
            for region in op.regions:
                for block in region.blocks:
                    for index, argument in enumerate(block.arguments):
                        name = argument.name or f"arg{index}"
                        self._bind(env, scope, name, argument.type, argument, op, False)
            for result in op.results:
                if not result.name:
                    continue
                self._bind(env, scope, result.name, result.type, result, op, False)

        self.root.walk(visit)

    def _scope_name(self, op: Operation) -> str:
        """The name of the symbol-carrying ancestor (or the op itself)."""
        from mlir.ir import SymbolTable

        current: Optional[Operation] = op
        while current is not None:
            symbol = SymbolTable.get_symbol_name(current)
            if symbol is not None and current.name != "builtin.module":
                return symbol
            current = current.parent_op
        return self.symbols.root_scope.name

    def _bind(
        self,
        env: TypeEnvironment,
        scope: str,
        name: str,
        type: Optional[Type],
        value: Optional[Value],
        op: Optional[Operation],
        inferred: bool,
    ) -> TypeBinding:
        key = f"{scope}::{name}" if scope else name
        binding = TypeBinding(
            key=key,
            type=type,
            sort=sort_of(type),
            width=width_of(type),
            value=value,
            op=op,
            inferred=inferred,
        )
        return env.bind(binding)

    # -- inference --------------------------------------------------------
    def _infer_once(self, resolution: TypeResolution) -> bool:
        """One inference sweep.  Returns ``True`` when something changed."""
        env = resolution.environment
        changed = False

        def visit(op: Operation) -> None:
            nonlocal changed
            for result in op.results:
                binding = env.lookup_value(result)
                if binding is not None and binding.is_resolved:
                    continue
                inferred = self.infer_result_type(op, result, env)
                if inferred is None:
                    continue
                scope = self._scope_name(op)
                name = result.name or f"{op.mnemonic}{result.index}"
                previous = binding.type if binding is not None else None
                if previous is not None and previous != inferred:
                    resolution.conflicts.append(
                        TypeConflict(name, previous, inferred, op)
                    )
                    continue
                self._bind(env, scope, name, inferred, result, op, True)
                # Keep the IR and the analysis in agreement.
                result.type = inferred
                changed = True

        self.root.walk(visit)
        return changed

    def infer_result_type(
        self,
        op: Operation,
        result: OpResult,
        env: Optional[TypeEnvironment] = None,
    ) -> Optional[Type]:
        """Infer the type of ``result`` from ``op``'s operands and attributes."""
        env = env if env is not None else TypeEnvironment()

        if op.name in SINGLE_BIT_RESULT_OPS:
            return IntegerType(1)

        value_attr = op.attributes.get("value")
        declared = getattr(value_attr, "type", None)
        if declared is not None:
            return declared

        operand_types = [self._operand_type(operand, env) for operand in op.operands]
        known = [t for t in operand_types if t is not None]

        if op.name in SUMMED_WIDTH_OPS:
            widths = [width_of(t) for t in known]
            if widths and all(widths):
                return IntegerType(sum(widths))
            return None

        index = _FORWARDED_OPERAND.get(op.name)
        if index is not None and index < len(operand_types):
            return operand_types[index]

        # The general rule: same-typed operands give a same-typed result, which
        # covers every ``comb``/``arith`` binary operation.
        for candidate in known:
            if sort_of(candidate) in (Sort.INT, Sort.BOOL):
                return candidate
        return known[0] if known else None

    def _operand_type(
        self, operand: Any, env: TypeEnvironment
    ) -> Optional[Type]:
        if isinstance(operand, Value):
            binding = env.lookup_value(operand)
            if binding is not None and binding.type is not None:
                return binding.type
            return operand.type
        binding = env.lookup(operand)
        return binding.type if binding is not None else None

    # -- shorthand --------------------------------------------------------
    @property
    def resolution(self) -> TypeResolution:
        return self.resolve()

    @property
    def environment(self) -> TypeEnvironment:
        return self.resolve().environment

    def type_of(self, key: Any) -> Optional[Type]:
        return self.resolve().type_of(key)

    def sort_of(self, key: Any) -> Sort:
        return self.resolve().sort_of(key)

    def width_of(self, key: Any) -> int:
        return self.resolve().width_of(key)

    def signature(self, symbol: str) -> Optional[FunctionType]:
        return self.resolve().signature(symbol)

    def return_type(self, symbol: str) -> Optional[Type]:
        """The declared result type of a function-like symbol."""
        return self.resolve().return_type(symbol)

    #: Spelled out for readers coming from the K side of the stack.
    resolve_return_type = return_type

    def result_type_name(self, symbol: str) -> str:
        """``str`` of the symbol's result type, e.g. ``"i32"``."""
        result = self.return_type(symbol)
        return str(result) if result is not None else ""

    @property
    def num_typed(self) -> int:
        return self.resolve().num_typed

    def __len__(self) -> int:
        return len(self.resolve())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<TypeResolver root={self.root.name!r}>"


def resolve_types(
    root: Operation, symbols: Optional[SymbolResolution] = None
) -> TypeResolution:
    """Convenience wrapper: ``resolve_types(module).return_type("f")``."""
    return TypeResolver(root, symbols).resolve()

input.content:
"""Attribute analysis: turning MLIR attributes into semantic values.

Rules cannot rewrite an :class:`~src.mlir.ir.Attribute`; they need the value
inside it.  This module performs that unwrapping once, up front, so the rule set
in :mod:`src.k_circt.semantics` only ever deals with Python integers, strings and
lists:

* ``IntegerAttr(42, i32)``      -> ``42``
* ``StringAttr("eq")``          -> ``"eq"``
* ``ArrayAttr([...])``          -> ``[...]`` (recursively resolved)
* ``TypeAttr((i32) -> i32)``    -> the :class:`~src.mlir.ir.Type` itself
* ``FlatSymbolRefAttr("@f")``   -> the *operation* ``@f`` names, looked up
  through :mod:`src.k_circt.symbols`

The last case is why this is an analysis rather than a one-line helper: resolving
a symbol-valued attribute needs the scope tree, so attribute resolution is
layered on top of symbol resolution exactly as it is in a K definition.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Sequence, Tuple

from mlir.ir import (
    ArrayAttr,
    Attribute,
    BoolAttr,
    DictAttr,
    FlatSymbolRefAttr,
    FloatAttr,
    IntegerAttr,
    Operation,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    UnitAttr,
)

from .symbols import SymbolResolution, SymbolResolver

__all__ = [
    "ResolvedAttribute",
    "AttributeResolution",
    "AttributeResolver",
    "resolve_attributes",
]

#: Attributes that carry structural bookkeeping rather than semantic values.
STRUCTURAL_ATTRIBUTES = frozenset(
    {"port_names", "port_directions", "assembly_keywords", "operand_segment_sizes"}
)


@dataclass
class ResolvedAttribute:
    """One attribute, unwrapped."""

    op: Operation
    name: str
    attribute: Attribute
    value: Any
    type: Optional[Type] = None
    symbol_target: Optional[Operation] = None

    @property
    def owner_name(self) -> str:
        return self.op.name

    @property
    def is_symbol(self) -> bool:
        return isinstance(self.attribute, FlatSymbolRefAttr)

    @property
    def is_resolved(self) -> bool:
        if self.is_symbol:
            return self.symbol_target is not None
        return self.value is not None

    def __str__(self) -> str:
        suffix = f" : {self.type}" if self.type is not None else ""
        return f"{self.op.name}.{self.name} = {self.value!r}{suffix}"


@dataclass
class AttributeResolution:
    """The result of running :class:`AttributeResolver` over a whole tree."""

    bindings: List[ResolvedAttribute] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)

    # -- counts -----------------------------------------------------------
    @property
    def num_resolved(self) -> int:
        return sum(1 for b in self.bindings if b.is_resolved)

    @property
    def num_attributes(self) -> int:
        return len(self.bindings)

    @property
    def unresolved(self) -> List[ResolvedAttribute]:
        return [b for b in self.bindings if not b.is_resolved]

    @property
    def is_complete(self) -> bool:
        return not self.unresolved and not self.errors

    # -- lookup -----------------------------------------------------------
    def for_operation(self, op: Operation) -> Dict[str, Any]:
        return {b.name: b.value for b in self.bindings if b.op is op}

    def named(self, name: str) -> List[ResolvedAttribute]:
        return [b for b in self.bindings if b.name == name]

    def values(self, name: str) -> List[Any]:
        return [b.value for b in self.named(name)]

    def first(self, name: str, default: Any = None) -> Any:
        found = self.named(name)
        return found[0].value if found else default

    def __len__(self) -> int:
        return len(self.bindings)

    def to_text(self) -> str:
        return "\n".join(str(b) for b in self.bindings)


class AttributeResolver:
    """Unwraps attributes into Python values, resolving symbol references."""

    def __init__(
        self,
        root: Optional[Operation] = None,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        if symbols is not None:
            self.symbols: Optional[SymbolResolution] = symbols
        elif root is not None:
            self.symbols = SymbolResolver(root).resolve()
        else:
            self.symbols = None
        self._resolution: Optional[AttributeResolution] = None

    # -- single attributes ------------------------------------------------
    def resolve(self, attr: Optional[Attribute]) -> Any:
        """Unwrap one attribute into a plain Python value."""
        if attr is None:
            return None
        if isinstance(attr, (IntegerAttr,)):
            return int(attr.value)
        if isinstance(attr, BoolAttr):
            return bool(attr.value)
        if isinstance(attr, FloatAttr):
            return float(attr.value)
        if isinstance(attr, StringAttr):
            return attr.value
        if isinstance(attr, TypeAttr):
            return attr.value
        if isinstance(attr, UnitAttr):
            return True
        if isinstance(attr, FlatSymbolRefAttr):
            return str(attr.value)
        if isinstance(attr, ArrayAttr):
            return [self.resolve(element) for element in attr.value]
        if isinstance(attr, DictAttr):
            return {key: self.resolve(item) for key, item in attr.value.items()}
        return attr.value

    def resolve_attribute(
        self, op: Operation, name: str, default: Any = None
    ) -> Any:
        """The resolved value of ``op``'s ``name`` attribute."""
        attr = op.attributes.get(name)
        if attr is None:
            return default
        return self.resolve(attr)

    def resolve_operation(self, op: Operation) -> Dict[str, Any]:
        """Every attribute of ``op``, resolved."""
        return {name: self.resolve(attr) for name, attr in op.attributes.items()}

    def resolve_symbol(self, attr: Optional[Attribute]) -> Optional[Operation]:
        """The operation a symbol-valued attribute refers to."""
        if attr is None or self.symbols is None:
            return None
        name = self.resolve(attr)
        if not isinstance(name, str):
            return None
        return self.symbols.operation(name)

    def attribute_type(self, attr: Optional[Attribute]) -> Optional[Type]:
        """The type annotation carried by a typed attribute, if any."""
        if attr is None:
            return None
        if isinstance(attr, TypeAttr):
            return attr.value
        return getattr(attr, "type", None)

    # -- constants ---------------------------------------------------------
    def constant_value(self, op: Operation) -> Optional[int]:
        """The integer a constant-like operation carries."""
        if not op.has_trait(Trait.CONSTANT_LIKE) and not op.name.endswith(".constant"):
            return None
        value = self.resolve_attribute(op, "value")
        return int(value) if isinstance(value, (int, float, bool)) else None

    def constants(self, scope: Optional[str] = None) -> List[Tuple[str, int]]:
        """Every ``(ssa name, value)`` constant pair, optionally within ``scope``."""
        found: List[Tuple[str, int]] = []
        for op in self._scope_operations(scope):
            value = self.constant_value(op)
            if value is None:
                continue
            name = op.result(0).name if op.num_results else ""
            found.append((name or "", value))
        return found

    def lookup_constant(self, name: str, scope: Optional[str] = None) -> Optional[int]:
        """The value of the constant bound to SSA name ``name``."""
        wanted = name.lstrip("%")
        for ssa_name, value in self.constants(scope):
            if ssa_name == wanted:
                return value
        return None

    def first_constant(self, scope: Optional[str] = None) -> Optional[int]:
        """The value of the first constant in textual order."""
        constants = self.constants(scope)
        return constants[0][1] if constants else None

    def _scope_operations(self, scope: Optional[str]) -> List[Operation]:
        """Operations under ``scope`` (a symbol name), or the whole tree."""
        root = self.root
        if scope is not None and self.symbols is not None:
            candidate = self.symbols.operation(scope)
            if candidate is not None:
                root = candidate
        if root is None:
            return []
        collected: List[Operation] = []
        root.walk(collected.append)
        return collected

    # -- whole-tree analysis ----------------------------------------------
    def resolve_all(self) -> AttributeResolution:
        """Resolve every attribute in the tree (cached)."""
        if self._resolution is not None:
            return self._resolution
        resolution = AttributeResolution()
        if self.root is None:
            self._resolution = resolution
            return resolution

        def visit(op: Operation) -> None:
            for name, attr in op.attributes.items():
                if name in STRUCTURAL_ATTRIBUTES:
                    continue
                binding = ResolvedAttribute(
                    op=op,
                    name=name,
                    attribute=attr,
                    value=self.resolve(attr),
                    type=self.attribute_type(attr),
                )
                if binding.is_symbol:
                    binding.symbol_target = self.resolve_symbol(attr)
                    if binding.symbol_target is None:
                        resolution.errors.append(
                            f"'{op.name}' refers to unknown symbol @{binding.value}"
                        )
                resolution.bindings.append(binding)

        self.root.walk(visit)
        self._resolution = resolution
        return resolution

    @property
    def resolution(self) -> AttributeResolution:
        return self.resolve_all()

    @property
    def num_resolved(self) -> int:
        return self.resolve_all().num_resolved

    def __len__(self) -> int:
        return len(self.resolve_all())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        label = self.root.name if self.root is not None else "<none>"
        return f"<AttributeResolver root={label!r}>"


def resolve_attributes(
    root: Operation, symbols: Optional[SymbolResolution] = None
) -> AttributeResolution:
    """Convenience wrapper: ``resolve_attributes(module).num_resolved``."""
    return AttributeResolver(root, symbols).resolve_all()

toolUseResult.content:
"""Attribute analysis: turning MLIR attributes into semantic values.

Rules cannot rewrite an :class:`~src.mlir.ir.Attribute`; they need the value
inside it.  This module performs that unwrapping once, up front, so the rule set
in :mod:`src.k_circt.semantics` only ever deals with Python integers, strings and
lists:

* ``IntegerAttr(42, i32)``      -> ``42``
* ``StringAttr("eq")``          -> ``"eq"``
* ``ArrayAttr([...])``          -> ``[...]`` (recursively resolved)
* ``TypeAttr((i32) -> i32)``    -> the :class:`~src.mlir.ir.Type` itself
* ``FlatSymbolRefAttr("@f")``   -> the *operation* ``@f`` names, looked up
  through :mod:`src.k_circt.symbols`

The last case is why this is an analysis rather than a one-line helper: resolving
a symbol-valued attribute needs the scope tree, so attribute resolution is
layered on top of symbol resolution exactly as it is in a K definition.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Sequence, Tuple

from mlir.ir import (
    ArrayAttr,
    Attribute,
    BoolAttr,
    DictAttr,
    FlatSymbolRefAttr,
    FloatAttr,
    IntegerAttr,
    Operation,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    UnitAttr,
)

from .symbols import SymbolResolution, SymbolResolver

__all__ = [
    "ResolvedAttribute",
    "AttributeResolution",
    "AttributeResolver",
    "resolve_attributes",
]

#: Attributes that carry structural bookkeeping rather than semantic values.
STRUCTURAL_ATTRIBUTES = frozenset(
    {"port_names", "port_directions", "assembly_keywords", "operand_segment_sizes"}
)


@dataclass
class ResolvedAttribute:
    """One attribute, unwrapped."""

    op: Operation
    name: str
    attribute: Attribute
    value: Any
    type: Optional[Type] = None
    symbol_target: Optional[Operation] = None

    @property
    def owner_name(self) -> str:
        return self.op.name

    @property
    def is_symbol(self) -> bool:
        return isinstance(self.attribute, FlatSymbolRefAttr)

    @property
    def is_resolved(self) -> bool:
        if self.is_symbol:
            return self.symbol_target is not None
        return self.value is not None

    def __str__(self) -> str:
        suffix = f" : {self.type}" if self.type is not None else ""
        return f"{self.op.name}.{self.name} = {self.value!r}{suffix}"


@dataclass
class AttributeResolution:
    """The result of running :class:`AttributeResolver` over a whole tree."""

    bindings: List[ResolvedAttribute] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)

    # -- counts -----------------------------------------------------------
    @property
    def num_resolved(self) -> int:
        return sum(1 for b in self.bindings if b.is_resolved)

    @property
    def num_attributes(self) -> int:
        return len(self.bindings)

    @property
    def unresolved(self) -> List[ResolvedAttribute]:
        return [b for b in self.bindings if not b.is_resolved]

    @property
    def is_complete(self) -> bool:
        return not self.unresolved and not self.errors

    # -- lookup -----------------------------------------------------------
    def for_operation(self, op: Operation) -> Dict[str, Any]:
        return {b.name: b.value for b in self.bindings if b.op is op}

    def named(self, name: str) -> List[ResolvedAttribute]:
        return [b for b in self.bindings if b.name == name]

    def values(self, name: str) -> List[Any]:
        return [b.value for b in self.named(name)]

    def first(self, name: str, default: Any = None) -> Any:
        found = self.named(name)
        return found[0].value if found else default

    def __len__(self) -> int:
        return len(self.bindings)

    def to_text(self) -> str:
        return "\n".join(str(b) for b in self.bindings)


class AttributeResolver:
    """Unwraps attributes into Python values, resolving symbol references."""

    def __init__(
        self,
        root: Optional[Operation] = None,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        if symbols is not None:
            self.symbols: Optional[SymbolResolution] = symbols
        elif root is not None:
            self.symbols = SymbolResolver(root).resolve()
        else:
            self.symbols = None
        self._resolution: Optional[AttributeResolution] = None

    # -- single attributes ------------------------------------------------
    def resolve(self, attr: Optional[Attribute]) -> Any:
        """Unwrap one attribute into a plain Python value."""
        if attr is None:
            return None
        if isinstance(attr, (IntegerAttr,)):
            return int(attr.value)
        if isinstance(attr, BoolAttr):
            return bool(attr.value)
        if isinstance(attr, FloatAttr):
            return float(attr.value)
        if isinstance(attr, StringAttr):
            return attr.value
        if isinstance(attr, TypeAttr):
            return attr.value
        if isinstance(attr, UnitAttr):
            return True
        if isinstance(attr, FlatSymbolRefAttr):
            return str(attr.value)
        if isinstance(attr, ArrayAttr):
            return [self.resolve(element) for element in attr.value]
        if isinstance(attr, DictAttr):
            return {key: self.resolve(item) for key, item in attr.value.items()}
        return attr.value

    def resolve_attribute(
        self, op: Operation, name: str, default: Any = None
    ) -> Any:
        """The resolved value of ``op``'s ``name`` attribute."""
        attr = op.attributes.get(name)
        if attr is None:
            return default
        return self.resolve(attr)

    def resolve_operation(self, op: Operation) -> Dict[str, Any]:
        """Every attribute of ``op``, resolved."""
        return {name: self.resolve(attr) for name, attr in op.attributes.items()}

    def resolve_symbol(self, attr: Optional[Attribute]) -> Optional[Operation]:
        """The operation a symbol-valued attribute refers to."""
        if attr is None or self.symbols is None:
            return None
        name = self.resolve(attr)
        if not isinstance(name, str):
            return None
        return self.symbols.operation(name)

    def attribute_type(self, attr: Optional[Attribute]) -> Optional[Type]:
        """The type annotation carried by a typed attribute, if any."""
        if attr is None:
            return None
        if isinstance(attr, TypeAttr):
            return attr.value
        return getattr(attr, "type", None)

    # -- constants ---------------------------------------------------------
    def constant_value(self, op: Operation) -> Optional[int]:
        """The integer a constant-like operation carries."""
        if not op.has_trait(Trait.CONSTANT_LIKE) and not op.name.endswith(".constant"):
            return None
        value = self.resolve_attribute(op, "value")
        return int(value) if isinstance(value, (int, float, bool)) else None

    def constants(self, scope: Optional[str] = None) -> List[Tuple[str, int]]:
        """Every ``(ssa name, value)`` constant pair, optionally within ``scope``."""
        found: List[Tuple[str, int]] = []
        for op in self._scope_operations(scope):
            value = self.constant_value(op)
            if value is None:
                continue
            name = op.result(0).name if op.num_results else ""
            found.append((name or "", value))
        return found

    def lookup_constant(self, name: str, scope: Optional[str] = None) -> Optional[int]:
        """The value of the constant bound to SSA name ``name``."""
        wanted = name.lstrip("%")
        for ssa_name, value in self.constants(scope):
            if ssa_name == wanted:
                return value
        return None

    def first_constant(self, scope: Optional[str] = None) -> Optional[int]:
        """The value of the first constant in textual order."""
        constants = self.constants(scope)
        return constants[0][1] if constants else None

    def _scope_operations(self, scope: Optional[str]) -> List[Operation]:
        """Operations under ``scope`` (a symbol name), or the whole tree."""
        root = self.root
        if scope is not None and self.symbols is not None:
            candidate = self.symbols.operation(scope)
            if candidate is not None:
                root = candidate
        if root is None:
            return []
        collected: List[Operation] = []
        root.walk(collected.append)
        return collected

    # -- whole-tree analysis ----------------------------------------------
    def resolve_all(self) -> AttributeResolution:
        """Resolve every attribute in the tree (cached)."""
        if self._resolution is not None:
            return self._resolution
        resolution = AttributeResolution()
        if self.root is None:
            self._resolution = resolution
            return resolution

        def visit(op: Operation) -> None:
            for name, attr in op.attributes.items():
                if name in STRUCTURAL_ATTRIBUTES:
                    continue
                binding = ResolvedAttribute(
                    op=op,
                    name=name,
                    attribute=attr,
                    value=self.resolve(attr),
                    type=self.attribute_type(attr),
                )
                if binding.is_symbol:
                    binding.symbol_target = self.resolve_symbol(attr)
                    if binding.symbol_target is None:
                        resolution.errors.append(
                            f"'{op.name}' refers to unknown symbol @{binding.value}"
                        )
                resolution.bindings.append(binding)

        self.root.walk(visit)
        self._resolution = resolution
        return resolution

    @property
    def resolution(self) -> AttributeResolution:
        return self.resolve_all()

    @property
    def num_resolved(self) -> int:
        return self.resolve_all().num_resolved

    def __len__(self) -> int:
        return len(self.resolve_all())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        label = self.root.name if self.root is not None else "<none>"
        return f"<AttributeResolver root={label!r}>"


def resolve_attributes(
    root: Operation, symbols: Optional[SymbolResolution] = None
) -> AttributeResolution:
    """Convenience wrapper: ``resolve_attributes(module).num_resolved``."""
    return AttributeResolver(root, symbols).resolve_all()

input.content:
"""Stateful circuit execution: register cells and the cycle driver.

:mod:`src.k_circt.semantics` says what each operation *means*; this module holds
the state those rules read and write, and sequences a clock cycle:

1. seed ``<inputs>``/``<env>`` from the port values,
2. drain ``<k>`` with the combinational rules (registers read as ``<state>``),
3. run the sequential rules so every register stages its next value in
   ``<next>``,
4. fire :class:`~src.k_circt.semantics.ClockEdgeRule` to commit ``<next>`` into
   ``<state>`` and advance ``<cycle>``.

Steps 2 and 3 are deliberately separate: a register never observes another
register's post-edge value, which is what makes the counter in
``inputs/counter.mlir`` increment by exactly one per cycle.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional, Sequence, Tuple

from mlir.ir import Block, Operation, Trait, Value

from .configuration import KConfiguration
from .semantics import (
    CIRCUIT_RULES,
    RuleApplication,
    RuleEngine,
    RulePhase,
    RuleSet,
    SemanticError,
    register_key,
)

__all__ = [
    "RegisterCell",
    "CircuitState",
    "CycleResult",
    "StatefulCircuit",
    "execute_function",
]

#: Operations that own a hardware module body.
MODULE_OPS = ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")


# ---------------------------------------------------------------------------
# Register state
# ---------------------------------------------------------------------------


@dataclass
class RegisterCell:
    """One register's state, as it appears in the ``<state>`` cell."""

    name: str
    width: int = 0
    value: int = 0
    next_value: Optional[int] = None
    reset_value: int = 0
    op: Optional[Operation] = None
    cycles_latched: int = 0

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    def truncate(self, value: int) -> int:
        mask = self.mask()
        return int(value) & mask if mask else int(value)

    # -- two-phase update -------------------------------------------------
    def read(self) -> int:
        return self.value

    def write(self, value: int) -> int:
        self.value = self.truncate(value)
        return self.value

    def stage(self, value: int) -> int:
        self.next_value = self.truncate(value)
        return self.next_value

    def commit(self) -> int:
        if self.next_value is not None:
            self.value = self.next_value
            self.next_value = None
            self.cycles_latched += 1
        return self.value

    def reset(self) -> int:
        self.value = self.truncate(self.reset_value)
        self.next_value = None
        self.cycles_latched = 0
        return self.value

    def __str__(self) -> str:
        return f"{self.name} |-> {self.value} (i{self.width})"


class CircuitState:
    """The register state of one circuit, keyed by register name."""

    def __init__(self, cells: Optional[Sequence[RegisterCell]] = None) -> None:
        self.cells: Dict[str, RegisterCell] = {}
        for cell in cells or ():
            self.cells[cell.name] = cell

    # -- construction -----------------------------------------------------
    @classmethod
    def from_module(
        cls, module: Operation, rules: Optional[RuleSet] = None
    ) -> "CircuitState":
        """Discover every register in ``module``'s body.

        A "register" is any operation the rule set gives a *sequential* rule, so
        adding a stateful operation to the semantics automatically teaches the
        executor about it.
        """
        rule_set = rules if rules is not None else CIRCUIT_RULES
        cells: List[RegisterCell] = []
        for op in _body_operations(module):
            if not rule_set.rules_for(op.name, RulePhase.SEQUENTIAL):
                continue
            cells.append(
                RegisterCell(
                    name=register_key(op),
                    width=_width_of_op(op),
                    reset_value=_reset_value_of(op),
                    op=op,
                )
            )
        state = cls(cells)
        state.reset()
        return state

    # -- access -----------------------------------------------------------
    def cell(self, name: str) -> Optional[RegisterCell]:
        return self.cells.get(name)

    def read(self, name: str, default: int = 0) -> int:
        cell = self.cells.get(name)
        return cell.value if cell is not None else int(default)

    def write(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.write(value)

    def stage(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.stage(value)

    def commit(self) -> Dict[str, int]:
        return {name: cell.commit() for name, cell in self.cells.items()}

    def reset(self) -> Dict[str, int]:
        return {name: cell.reset() for name, cell in self.cells.items()}

    # -- views -------------------------------------------------------------
    def snapshot(self) -> Dict[str, int]:
        return {name: cell.value for name, cell in self.cells.items()}

    def names(self) -> List[str]:
        return list(self.cells)

    @property
    def registers(self) -> List[RegisterCell]:
        return list(self.cells.values())

    @property
    def is_stateful(self) -> bool:
        return bool(self.cells)

    # -- configuration interop --------------------------------------------
    def load_into(self, config: KConfiguration) -> KConfiguration:
        """Copy this state into a configuration's ``<state>`` cell."""
        config.state.clear()
        config.state.update(self.snapshot())
        return config

    def sync_from(self, config: KConfiguration) -> "CircuitState":
        """Adopt the values a rule left in ``<state>``."""
        for name, value in config.state.items():
            self.write(name, value)
        return self

    def __len__(self) -> int:
        return len(self.cells)

    def __iter__(self) -> Iterator[RegisterCell]:
        return iter(self.cells.values())

    def __contains__(self, name: str) -> bool:
        return name in self.cells

    def __str__(self) -> str:
        return " ".join(str(cell) for cell in self.cells.values()) or ".Map"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<CircuitState registers={list(self.cells)}>"


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _body_operations(module: Operation) -> List[Operation]:
    if not module.regions or not module.regions[0].blocks:
        return []
    return list(module.regions[0].blocks[0].operations)


def _width_of_op(op: Operation) -> int:
    from circt.hw_dialect import bit_width_of

    for result in op.results:
        width = bit_width_of(result.type)
        if width:
            return width
    return int(getattr(op, "_declared_width", 0) or 0)


def _reset_value_of(op: Operation) -> int:
    """The register's power-on value.

    ``seq.compreg %next, %clk reset %reset, %c0_i8`` names its reset value with
    an operand, so the constant behind that operand is read directly - the reset
    value has to be known before any rule has settled the design.
    """
    declared = int(getattr(op, "reset_value", 0) or 0)
    operands = op.operands
    if len(operands) <= 3:
        return declared
    operand = operands[3]
    if not isinstance(operand, Value):
        return declared
    defining = operand.defining_op
    if defining is None:
        return declared
    attr = defining.attributes.get("value")
    if attr is None or not defining.has_trait(Trait.CONSTANT_LIKE):
        return declared
    try:
        return int(attr.value)
    except (TypeError, ValueError):  # pragma: no cover - defensive
        return declared


# ---------------------------------------------------------------------------
# Cycle results
# ---------------------------------------------------------------------------


@dataclass
class CycleResult:
    """Everything one clock cycle produced."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    registers: Dict[str, int] = field(default_factory=dict)
    next_registers: Dict[str, int] = field(default_factory=dict)
    applications: List[RuleApplication] = field(default_factory=list)

    @property
    def num_steps(self) -> int:
        return len(self.applications)

    def rule_names(self) -> List[str]:
        return [application.rule for application in self.applications]

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        if name is None:
            return next(iter(self.outputs.values()), default)
        return self.outputs.get(name, default)

    def __str__(self) -> str:
        parts = [f"cycle={self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("state", self.registers),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        parts.append(f"steps={self.num_steps}")
        return " ".join(parts)


# ---------------------------------------------------------------------------
# Executor
# ---------------------------------------------------------------------------


class StatefulCircuit:
    """Executes an ``hw.module`` through the semantic rules, cycle by cycle."""

    def __init__(
        self,
        module: Operation,
        rules: Optional[RuleSet] = None,
        engine: Optional[RuleEngine] = None,
    ) -> None:
        if module.name not in MODULE_OPS:
            raise SemanticError(
                f"expected a hardware module operation, got '{module.name}'"
            )
        self.module = module
        self.rules = rules if rules is not None else CIRCUIT_RULES
        self.engine = engine if engine is not None else RuleEngine(self.rules)
        self.config = KConfiguration.initial()
        self.state = CircuitState.from_module(module, self.rules)

        self._body: List[Operation] = _body_operations(module)
        self._ports = list(getattr(module, "ports", []) or [])
        self._input_ports = [p for p in self._ports if not p.is_output]
        self._output_ports = [p for p in self._ports if p.is_output]
        self._registers = [
            cell.op for cell in self.state.registers if cell.op is not None
        ]
        self.inputs: Dict[str, int] = {p.name: 0 for p in self._input_ports}
        self.reset()

    # -- structure --------------------------------------------------------
    @property
    def ports(self) -> List[Any]:
        return list(self._ports)

    @property
    def input_names(self) -> List[str]:
        return [p.name for p in self._input_ports]

    @property
    def output_names(self) -> List[str]:
        return [p.name for p in self._output_ports]

    @property
    def body(self) -> List[Operation]:
        return list(self._body)

    @property
    def registers(self) -> List[RegisterCell]:
        return self.state.registers

    @property
    def is_sequential(self) -> bool:
        return self.state.is_stateful

    @property
    def cycle(self) -> int:
        return self.config.cycle

    # -- lifecycle --------------------------------------------------------
    def reset(self) -> "StatefulCircuit":
        """Assert reset: clear the configuration and re-seed register state."""
        self.config.reset()
        self.state.reset()
        self.state.load_into(self.config)
        self.engine.reset()
        return self

    def set_input(self, name: str, value: int) -> None:
        if name not in self.inputs:
            raise SemanticError(f"'{name}' is not an input port of this module")
        self.inputs[name] = int(value)

    def set_inputs(self, values: Optional[Dict[str, int]]) -> None:
        for name, value in (values or {}).items():
            self.set_input(name, value)

    # -- phase 1: combinational settle ------------------------------------
    def settle(
        self, inputs: Optional[Dict[str, int]] = None
    ) -> List[RuleApplication]:
        """Bind the ports, then drain ``<k>`` with the combinational rules."""
        self.set_inputs(inputs)
        self._seed_environment()
        return self.engine.settle(self.config, self._body)

    def _seed_environment(self) -> None:
        config = self.config
        config.cell("env").clear()
        config.cell("outputs").clear()
        config.inputs.clear()
        config.inputs.update(self.inputs)
        self.state.load_into(config)

        block = self._entry_block()
        if block is None:
            return
        for index, argument in enumerate(block.arguments):
            name = (
                self._input_ports[index].name
                if index < len(self._input_ports)
                else (argument.name or f"arg{index}")
            )
            value = int(self.inputs.get(name, 0))
            config.bind(argument, value)
            if name:
                config.bind(name, value)

    def _entry_block(self) -> Optional[Block]:
        if not self.module.regions or not self.module.regions[0].blocks:
            return None
        return self.module.regions[0].blocks[0]

    # -- phase 2: clock edge ----------------------------------------------
    def step(self, inputs: Optional[Dict[str, int]] = None) -> CycleResult:
        """Advance one clock cycle and report what happened."""
        applications = list(self.settle(inputs))
        before = self.state.snapshot()
        outputs = dict(self.config.outputs)

        applications.extend(self.engine.latch(self.config, self._registers))
        staged = dict(self.config.next_state)
        cycle = self.config.cycle
        applications.append(self.engine.clock_edge(self.config))
        self.state.sync_from(self.config)

        return CycleResult(
            cycle=cycle,
            inputs=dict(self.inputs),
            outputs=outputs,
            registers=before,
            next_registers=staged,
            applications=applications,
        )

    def run(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        stimulus: Optional[Sequence[Dict[str, int]]] = None,
    ) -> List[CycleResult]:
        """Run ``cycles`` clock cycles, returning one result per cycle."""
        self.set_inputs(inputs)
        results: List[CycleResult] = []
        for index in range(max(0, cycles)):
            override = None
            if stimulus is not None and index < len(stimulus):
                override = stimulus[index]
            results.append(self.step(override))
        return results

    # -- reading results --------------------------------------------------
    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle without a clock edge and return the module outputs."""
        self.settle(inputs)
        return dict(self.config.outputs)

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        outputs = self.config.outputs
        if name is None:
            return next(iter(outputs.values()), default)
        if name not in outputs:
            raise SemanticError(f"'{name}' is not an output port of this module")
        return outputs[name]

    def output_after(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        name: Optional[str] = None,
    ) -> int:
        """Run ``cycles`` cycles, settle once more, then read an output."""
        self.run(cycles, inputs)
        self.settle()
        return self.output(name)

    def register_values(self) -> Dict[str, int]:
        return self.state.snapshot()

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        symbol = self.module.attributes.get("sym_name")
        label = symbol.value if symbol is not None else "?"
        return (
            f"<StatefulCircuit @{label} ports={len(self._ports)} "
            f"registers={len(self.state)} cycle={self.cycle}>"
        )


# ---------------------------------------------------------------------------
# Functional (arith / func) execution
# ---------------------------------------------------------------------------


def execute_function(
    func: Operation,
    arguments: Optional[Sequence[int]] = None,
    rules: Optional[RuleSet] = None,
) -> Dict[str, int]:
    """Evaluate a single-block ``func.func`` body through the same rules.

    This is what connects the semantic layer back to the MLIR sample input: the
    ``arith`` rules in :mod:`src.k_circt.semantics` evaluate ``@fold_chain``
    without the circuit machinery being involved at all.
    """
    if func.name not in ("func.func", "builtin.func"):
        raise SemanticError(f"expected a function operation, got '{func.name}'")
    if not func.regions or not func.regions[0].blocks:
        return {}

    engine = RuleEngine(rules if rules is not None else CIRCUIT_RULES)
    config = KConfiguration.initial()
    block = func.regions[0].blocks[0]

    supplied = list(arguments or ())
    for index, argument in enumerate(block.arguments):
        value = supplied[index] if index < len(supplied) else 0
        config.bind(argument, int(value))
        if argument.name:
            config.bind(argument.name, int(value))

    config.enqueue_all(list(block.operations))
    engine.run(config, RulePhase.FUNCTIONAL)
    return dict(config.outputs)

toolUseResult.content:
"""Stateful circuit execution: register cells and the cycle driver.

:mod:`src.k_circt.semantics` says what each operation *means*; this module holds
the state those rules read and write, and sequences a clock cycle:

1. seed ``<inputs>``/``<env>`` from the port values,
2. drain ``<k>`` with the combinational rules (registers read as ``<state>``),
3. run the sequential rules so every register stages its next value in
   ``<next>``,
4. fire :class:`~src.k_circt.semantics.ClockEdgeRule` to commit ``<next>`` into
   ``<state>`` and advance ``<cycle>``.

Steps 2 and 3 are deliberately separate: a register never observes another
register's post-edge value, which is what makes the counter in
``inputs/counter.mlir`` increment by exactly one per cycle.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional, Sequence, Tuple

from mlir.ir import Block, Operation, Trait, Value

from .configuration import KConfiguration
from .semantics import (
    CIRCUIT_RULES,
    RuleApplication,
    RuleEngine,
    RulePhase,
    RuleSet,
    SemanticError,
    register_key,
)

__all__ = [
    "RegisterCell",
    "CircuitState",
    "CycleResult",
    "StatefulCircuit",
    "execute_function",
]

#: Operations that own a hardware module body.
MODULE_OPS = ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")


# ---------------------------------------------------------------------------
# Register state
# ---------------------------------------------------------------------------


@dataclass
class RegisterCell:
    """One register's state, as it appears in the ``<state>`` cell."""

    name: str
    width: int = 0
    value: int = 0
    next_value: Optional[int] = None
    reset_value: int = 0
    op: Optional[Operation] = None
    cycles_latched: int = 0

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    def truncate(self, value: int) -> int:
        mask = self.mask()
        return int(value) & mask if mask else int(value)

    # -- two-phase update -------------------------------------------------
    def read(self) -> int:
        return self.value

    def write(self, value: int) -> int:
        self.value = self.truncate(value)
        return self.value

    def stage(self, value: int) -> int:
        self.next_value = self.truncate(value)
        return self.next_value

    def commit(self) -> int:
        if self.next_value is not None:
            self.value = self.next_value
            self.next_value = None
            self.cycles_latched += 1
        return self.value

    def reset(self) -> int:
        self.value = self.truncate(self.reset_value)
        self.next_value = None
        self.cycles_latched = 0
        return self.value

    def __str__(self) -> str:
        return f"{self.name} |-> {self.value} (i{self.width})"


class CircuitState:
    """The register state of one circuit, keyed by register name."""

    def __init__(self, cells: Optional[Sequence[RegisterCell]] = None) -> None:
        self.cells: Dict[str, RegisterCell] = {}
        for cell in cells or ():
            self.cells[cell.name] = cell

    # -- construction -----------------------------------------------------
    @classmethod
    def from_module(
        cls, module: Operation, rules: Optional[RuleSet] = None
    ) -> "CircuitState":
        """Discover every register in ``module``'s body.

        A "register" is any operation the rule set gives a *sequential* rule, so
        adding a stateful operation to the semantics automatically teaches the
        executor about it.
        """
        rule_set = rules if rules is not None else CIRCUIT_RULES
        cells: List[RegisterCell] = []
        for op in _body_operations(module):
            if not rule_set.rules_for(op.name, RulePhase.SEQUENTIAL):
                continue
            cells.append(
                RegisterCell(
                    name=register_key(op),
                    width=_width_of_op(op),
                    reset_value=_reset_value_of(op),
                    op=op,
                )
            )
        state = cls(cells)
        state.reset()
        return state

    # -- access -----------------------------------------------------------
    def cell(self, name: str) -> Optional[RegisterCell]:
        return self.cells.get(name)

    def read(self, name: str, default: int = 0) -> int:
        cell = self.cells.get(name)
        return cell.value if cell is not None else int(default)

    def write(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.write(value)

    def stage(self, name: str, value: int) -> int:
        cell = self.cells.get(name)
        if cell is None:
            cell = self.cells.setdefault(name, RegisterCell(name=name))
        return cell.stage(value)

    def commit(self) -> Dict[str, int]:
        return {name: cell.commit() for name, cell in self.cells.items()}

    def reset(self) -> Dict[str, int]:
        return {name: cell.reset() for name, cell in self.cells.items()}

    # -- views -------------------------------------------------------------
    def snapshot(self) -> Dict[str, int]:
        return {name: cell.value for name, cell in self.cells.items()}

    def names(self) -> List[str]:
        return list(self.cells)

    @property
    def registers(self) -> List[RegisterCell]:
        return list(self.cells.values())

    @property
    def is_stateful(self) -> bool:
        return bool(self.cells)

    # -- configuration interop --------------------------------------------
    def load_into(self, config: KConfiguration) -> KConfiguration:
        """Copy this state into a configuration's ``<state>`` cell."""
        config.state.clear()
        config.state.update(self.snapshot())
        return config

    def sync_from(self, config: KConfiguration) -> "CircuitState":
        """Adopt the values a rule left in ``<state>``."""
        for name, value in config.state.items():
            self.write(name, value)
        return self

    def __len__(self) -> int:
        return len(self.cells)

    def __iter__(self) -> Iterator[RegisterCell]:
        return iter(self.cells.values())

    def __contains__(self, name: str) -> bool:
        return name in self.cells

    def __str__(self) -> str:
        return " ".join(str(cell) for cell in self.cells.values()) or ".Map"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<CircuitState registers={list(self.cells)}>"


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _body_operations(module: Operation) -> List[Operation]:
    if not module.regions or not module.regions[0].blocks:
        return []
    return list(module.regions[0].blocks[0].operations)


def _width_of_op(op: Operation) -> int:
    from circt.hw_dialect import bit_width_of

    for result in op.results:
        width = bit_width_of(result.type)
        if width:
            return width
    return int(getattr(op, "_declared_width", 0) or 0)


def _reset_value_of(op: Operation) -> int:
    """The register's power-on value.

    ``seq.compreg %next, %clk reset %reset, %c0_i8`` names its reset value with
    an operand, so the constant behind that operand is read directly - the reset
    value has to be known before any rule has settled the design.
    """
    declared = int(getattr(op, "reset_value", 0) or 0)
    operands = op.operands
    if len(operands) <= 3:
        return declared
    operand = operands[3]
    if not isinstance(operand, Value):
        return declared
    defining = operand.defining_op
    if defining is None:
        return declared
    attr = defining.attributes.get("value")
    if attr is None or not defining.has_trait(Trait.CONSTANT_LIKE):
        return declared
    try:
        return int(attr.value)
    except (TypeError, ValueError):  # pragma: no cover - defensive
        return declared


# ---------------------------------------------------------------------------
# Cycle results
# ---------------------------------------------------------------------------


@dataclass
class CycleResult:
    """Everything one clock cycle produced."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    registers: Dict[str, int] = field(default_factory=dict)
    next_registers: Dict[str, int] = field(default_factory=dict)
    applications: List[RuleApplication] = field(default_factory=list)

    @property
    def num_steps(self) -> int:
        return len(self.applications)

    def rule_names(self) -> List[str]:
        return [application.rule for application in self.applications]

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        if name is None:
            return next(iter(self.outputs.values()), default)
        return self.outputs.get(name, default)

    def __str__(self) -> str:
        parts = [f"cycle={self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("state", self.registers),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        parts.append(f"steps={self.num_steps}")
        return " ".join(parts)


# ---------------------------------------------------------------------------
# Executor
# ---------------------------------------------------------------------------


class StatefulCircuit:
    """Executes an ``hw.module`` through the semantic rules, cycle by cycle."""

    def __init__(
        self,
        module: Operation,
        rules: Optional[RuleSet] = None,
        engine: Optional[RuleEngine] = None,
    ) -> None:
        if module.name not in MODULE_OPS:
            raise SemanticError(
                f"expected a hardware module operation, got '{module.name}'"
            )
        self.module = module
        self.rules = rules if rules is not None else CIRCUIT_RULES
        self.engine = engine if engine is not None else RuleEngine(self.rules)
        self.config = KConfiguration.initial()
        self.state = CircuitState.from_module(module, self.rules)

        self._body: List[Operation] = _body_operations(module)
        self._ports = list(getattr(module, "ports", []) or [])
        self._input_ports = [p for p in self._ports if not p.is_output]
        self._output_ports = [p for p in self._ports if p.is_output]
        self._registers = [
            cell.op for cell in self.state.registers if cell.op is not None
        ]
        self.inputs: Dict[str, int] = {p.name: 0 for p in self._input_ports}
        self.reset()

    # -- structure --------------------------------------------------------
    @property
    def ports(self) -> List[Any]:
        return list(self._ports)

    @property
    def input_names(self) -> List[str]:
        return [p.name for p in self._input_ports]

    @property
    def output_names(self) -> List[str]:
        return [p.name for p in self._output_ports]

    @property
    def body(self) -> List[Operation]:
        return list(self._body)

    @property
    def registers(self) -> List[RegisterCell]:
        return self.state.registers

    @property
    def is_sequential(self) -> bool:
        return self.state.is_stateful

    @property
    def cycle(self) -> int:
        return self.config.cycle

    # -- lifecycle --------------------------------------------------------
    def reset(self) -> "StatefulCircuit":
        """Assert reset: clear the configuration and re-seed register state."""
        self.config.reset()
        self.state.reset()
        self.state.load_into(self.config)
        self.engine.reset()
        return self

    def set_input(self, name: str, value: int) -> None:
        if name not in self.inputs:
            raise SemanticError(f"'{name}' is not an input port of this module")
        self.inputs[name] = int(value)

    def set_inputs(self, values: Optional[Dict[str, int]]) -> None:
        for name, value in (values or {}).items():
            self.set_input(name, value)

    # -- phase 1: combinational settle ------------------------------------
    def settle(
        self, inputs: Optional[Dict[str, int]] = None
    ) -> List[RuleApplication]:
        """Bind the ports, then drain ``<k>`` with the combinational rules."""
        self.set_inputs(inputs)
        self._seed_environment()
        return self.engine.settle(self.config, self._body)

    def _seed_environment(self) -> None:
        config = self.config
        config.cell("env").clear()
        config.cell("outputs").clear()
        config.inputs.clear()
        config.inputs.update(self.inputs)
        self.state.load_into(config)

        block = self._entry_block()
        if block is None:
            return
        for index, argument in enumerate(block.arguments):
            name = (
                self._input_ports[index].name
                if index < len(self._input_ports)
                else (argument.name or f"arg{index}")
            )
            value = int(self.inputs.get(name, 0))
            config.bind(argument, value)
            if name:
                config.bind(name, value)

    def _entry_block(self) -> Optional[Block]:
        if not self.module.regions or not self.module.regions[0].blocks:
            return None
        return self.module.regions[0].blocks[0]

    # -- phase 2: clock edge ----------------------------------------------
    def step(self, inputs: Optional[Dict[str, int]] = None) -> CycleResult:
        """Advance one clock cycle and report what happened."""
        applications = list(self.settle(inputs))
        before = self.state.snapshot()
        outputs = dict(self.config.outputs)

        applications.extend(self.engine.latch(self.config, self._registers))
        staged = dict(self.config.next_state)
        cycle = self.config.cycle
        applications.append(self.engine.clock_edge(self.config))
        self.state.sync_from(self.config)

        return CycleResult(
            cycle=cycle,
            inputs=dict(self.inputs),
            outputs=outputs,
            registers=before,
            next_registers=staged,
            applications=applications,
        )

    def run(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        stimulus: Optional[Sequence[Dict[str, int]]] = None,
    ) -> List[CycleResult]:
        """Run ``cycles`` clock cycles, returning one result per cycle."""
        self.set_inputs(inputs)
        results: List[CycleResult] = []
        for index in range(max(0, cycles)):
            override = None
            if stimulus is not None and index < len(stimulus):
                override = stimulus[index]
            results.append(self.step(override))
        return results

    # -- reading results --------------------------------------------------
    def evaluate(self, inputs: Optional[Dict[str, int]] = None) -> Dict[str, int]:
        """Settle without a clock edge and return the module outputs."""
        self.settle(inputs)
        return dict(self.config.outputs)

    def output(self, name: Optional[str] = None, default: int = 0) -> int:
        outputs = self.config.outputs
        if name is None:
            return next(iter(outputs.values()), default)
        if name not in outputs:
            raise SemanticError(f"'{name}' is not an output port of this module")
        return outputs[name]

    def output_after(
        self,
        cycles: int,
        inputs: Optional[Dict[str, int]] = None,
        name: Optional[str] = None,
    ) -> int:
        """Run ``cycles`` cycles, settle once more, then read an output."""
        self.run(cycles, inputs)
        self.settle()
        return self.output(name)

    def register_values(self) -> Dict[str, int]:
        return self.state.snapshot()

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        symbol = self.module.attributes.get("sym_name")
        label = symbol.value if symbol is not None else "?"
        return (
            f"<StatefulCircuit @{label} ports={len(self._ports)} "
            f"registers={len(self.state)} cycle={self.cycle}>"
        )


# ---------------------------------------------------------------------------
# Functional (arith / func) execution
# ---------------------------------------------------------------------------


def execute_function(
    func: Operation,
    arguments: Optional[Sequence[int]] = None,
    rules: Optional[RuleSet] = None,
) -> Dict[str, int]:
    """Evaluate a single-block ``func.func`` body through the same rules.

    This is what connects the semantic layer back to the MLIR sample input: the
    ``arith`` rules in :mod:`src.k_circt.semantics` evaluate ``@fold_chain``
    without the circuit machinery being involved at all.
    """
    if func.name not in ("func.func", "builtin.func"):
        raise SemanticError(f"expected a function operation, got '{func.name}'")
    if not func.regions or not func.regions[0].blocks:
        return {}

    engine = RuleEngine(rules if rules is not None else CIRCUIT_RULES)
    config = KConfiguration.initial()
    block = func.regions[0].blocks[0]

    supplied = list(arguments or ())
    for index, argument in enumerate(block.arguments):
        value = supplied[index] if index < len(supplied) else 0
        config.bind(argument, int(value))
        if argument.name:
            config.bind(argument.name, int(value))

    config.enqueue_all(list(block.operations))
    engine.run(config, RulePhase.FUNCTIONAL)
    return dict(config.outputs)

input.content:
"""The Kimulator: a tracing interpreter over the semantic rules.

:class:`Kimulator` is the user-facing entry point of the semantic layer.  It ties
the pieces together - symbol analysis, type analysis, attribute resolution,
register state and the rule engine - and, unlike the plain simulator in
:mod:`src.circt.simulator`, it *records why* each value came out the way it did::

    >>> from mlir.parser import parse_file
    >>> import circt                      # registers hw / comb / seq
    >>> from k_circt import Kimulator
    >>> kim = Kimulator(parse_file("inputs/alu.mlir"), "ALU")
    >>> kim.evaluate({"a": 5, "b": 3, "op": 0})["result"]
    8
    >>> kim.trace_length                  # combinational probes do not tick
    0

Every clock cycle appends one :class:`TraceEntry` holding the inputs, the
register state before the edge, the settled outputs and the ordered list of
:class:`~src.k_circt.semantics.RuleApplication` records that produced them.  So
``len(kim.run(200))`` is 200, and ``kim.trace.total_steps`` is how many rules
fired to get there.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterator, List, Optional, Sequence, Union

from mlir.ir import ModuleOp, Operation

from .attributes import AttributeResolver
from .configuration import KConfiguration
from .semantics import (
    CIRCUIT_RULES,
    RuleApplication,
    RuleEngine,
    RuleSet,
    SemanticError,
)
from .state import CycleResult, MODULE_OPS, StatefulCircuit, execute_function
from .symbols import SymbolResolver
from .types import TypeResolver

__all__ = [
    "TraceEntry",
    "KTrace",
    "Kimulator",
    "find_hw_module",
    "kimulate",
]


# ---------------------------------------------------------------------------
# Trace records
# ---------------------------------------------------------------------------


@dataclass
class TraceEntry:
    """One clock cycle, plus the rules that fired during it."""

    cycle: int
    inputs: Dict[str, int] = field(default_factory=dict)
    outputs: Dict[str, int] = field(default_factory=dict)
    state: Dict[str, int] = field(default_factory=dict)
    next_state: Dict[str, int] = field(default_factory=dict)
    applications: List[RuleApplication] = field(default_factory=list)
    configuration: Optional[KConfiguration] = None

    @classmethod
    def from_cycle(
        cls, result: CycleResult, configuration: Optional[KConfiguration] = None
    ) -> "TraceEntry":
        return cls(
            cycle=result.cycle,
            inputs=dict(result.inputs),
            outputs=dict(result.outputs),
            state=dict(result.registers),
            next_state=dict(result.next_registers),
            applications=list(result.applications),
            configuration=configuration,
        )

    # -- queries ----------------------------------------------------------
    @property
    def num_steps(self) -> int:
        return len(self.applications)

    def rule_names(self) -> List[str]:
        return [application.rule for application in self.applications]

    def applications_of(self, rule: str) -> List[RuleApplication]:
        return [a for a in self.applications if a.rule == rule]

    def value(self, name: str, default: int = 0) -> int:
        for source in (self.outputs, self.state, self.inputs):
            if name in source:
                return source[name]
        return default

    def to_text(self, verbose: bool = False) -> str:
        parts = [f"cycle {self.cycle}"]
        for label, values in (
            ("in", self.inputs),
            ("state", self.state),
            ("out", self.outputs),
        ):
            if values:
                rendered = ", ".join(f"{k}={v}" for k, v in sorted(values.items()))
                parts.append(f"{label}({rendered})")
        header = " ".join(parts) + f" [{self.num_steps} rules]"
        if not verbose:
            return header
        lines = [header]
        lines.extend("    " + str(a) for a in self.applications)
        return "\n".join(lines)

    def __str__(self) -> str:
        return self.to_text()


class KTrace:
    """The sequence of cycles a :class:`Kimulator` executed."""

    def __init__(self, signals: Optional[Sequence[str]] = None) -> None:
        self.entries: List[TraceEntry] = []
        self.signals: List[str] = list(signals or ())

    # -- building ---------------------------------------------------------
    def append(self, entry: TraceEntry) -> TraceEntry:
        self.entries.append(entry)
        return entry

    def clear(self) -> None:
        self.entries.clear()

    # -- size -------------------------------------------------------------
    @property
    def length(self) -> int:
        return len(self.entries)

    def __len__(self) -> int:
        return len(self.entries)

    def __iter__(self) -> Iterator[TraceEntry]:
        return iter(self.entries)

    def __getitem__(self, index: int) -> TraceEntry:
        return self.entries[index]

    @property
    def total_steps(self) -> int:
        """How many rules fired across the whole trace."""
        return sum(entry.num_steps for entry in self.entries)

    # -- queries ----------------------------------------------------------
    @property
    def first(self) -> Optional[TraceEntry]:
        return self.entries[0] if self.entries else None

    @property
    def last(self) -> Optional[TraceEntry]:
        return self.entries[-1] if self.entries else None

    def at(self, cycle: int) -> Optional[TraceEntry]:
        for entry in self.entries:
            if entry.cycle == cycle:
                return entry
        return None

    def signal(self, name: str) -> List[int]:
        """One signal's value across every recorded cycle."""
        return [entry.value(name) for entry in self.entries]

    def outputs(self, name: Optional[str] = None) -> List[int]:
        series: List[int] = []
        for entry in self.entries:
            if name is None:
                series.append(next(iter(entry.outputs.values()), 0))
            else:
                series.append(entry.outputs.get(name, 0))
        return series

    def states(self, name: str) -> List[int]:
        return [entry.state.get(name, 0) for entry in self.entries]

    def applications(self) -> List[RuleApplication]:
        return [a for entry in self.entries for a in entry.applications]

    def rule_histogram(self) -> Dict[str, int]:
        """How many times each rule fired, useful for spotting dead rules."""
        histogram: Dict[str, int] = {}
        for application in self.applications():
            histogram[application.rule] = histogram.get(application.rule, 0) + 1
        return dict(sorted(histogram.items()))

    def to_text(self, verbose: bool = False) -> str:
        return "\n".join(entry.to_text(verbose) for entry in self.entries)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<KTrace cycles={len(self.entries)} steps={self.total_steps}>"


# ---------------------------------------------------------------------------
# Module lookup
# ---------------------------------------------------------------------------


def find_hw_module(root: Operation, name: Optional[str] = None) -> Operation:
    """Find a hardware module under ``root`` by symbol name.

    Accepts a module operation directly, so callers can pass either the parsed
    file or the ``hw.module`` they already located.
    """
    if root.name in MODULE_OPS:
        return root
    found: List[Operation] = []

    def visit(op: Operation) -> None:
        if op.name in MODULE_OPS:
            found.append(op)

    root.walk(visit)
    if not found:
        raise SemanticError("no hardware module operation found")
    if name is None:
        return found[0]
    wanted = name.lstrip("@")
    for candidate in found:
        symbol = candidate.attributes.get("sym_name")
        if symbol is not None and symbol.value == wanted:
            return candidate
    raise SemanticError(f"no hardware module named @{wanted}")


# ---------------------------------------------------------------------------
# Kimulator
# ---------------------------------------------------------------------------


class Kimulator:
    """Evaluates a circuit through explicit semantic rules, recording a trace."""

    def __init__(
        self,
        root: Operation,
        module_name: Optional[str] = None,
        rules: Optional[RuleSet] = None,
        record_configurations: bool = False,
    ) -> None:
        self.root = root
        self.rules = rules if rules is not None else CIRCUIT_RULES
        self.record_configurations = record_configurations
        self.module = find_hw_module(root, module_name)
        self.circuit = StatefulCircuit(self.module, self.rules)
        self.trace = KTrace(self.circuit.input_names + self.circuit.output_names)

