"""The CIRCT ``firrtl`` dialect and its width inference.

FIRRTL sits one level above ``hw``: it is the dialect a Chisel design lands in
before lowering.  Two things make it different from the rest of this layer and
are what this module models:

* **Widths may be unknown.**  ``!firrtl.uint`` with no width is legal; the
  compiler is expected to work the width out from context.  Every type here
  therefore carries ``width=None`` as a real state, not an error.
* **Connections are directional.**  A bundle field can be *flipped*, and
  ``firrtl.connect`` drives a destination from a source rather than producing a
  value, so the operations model assignment instead of dataflow.

:class:`WidthInference` implements the propagation rules FIRRTL specifies (an
add is one bit wider than its widest operand, a multiply is as wide as both
together, and so on) and iterates to a fixed point so a graph region resolves
regardless of the order values are defined in.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple, Union

from mlir.ir import (
    ArrayAttr,
    Attribute,
    Block,
    Dialect,
    FunctionType,
    IntegerAttr,
    Location,
    Operation,
    OpaqueType,
    Region,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    Value,
    get_default_context,
)

from .hw_dialect import (
    Direction,
    HWOp,
    IntType,
    Port,
    SignalEnv,
    bit_width_of,
)
from .seq_dialect import SeqOp

__all__ = [
    "FIRRTL_DIALECT",
    "FIRRTLType",
    "FIRRTLUIntType",
    "FIRRTLSIntType",
    "FIRRTLClockType",
    "FIRRTLResetType",
    "FIRRTLAnalogType",
    "FIRRTLBundleField",
    "FIRRTLBundleType",
    "FIRRTLVectorType",
    "FIRRTLCircuitOp",
    "FIRRTLModuleOp",
    "FIRRTLWireOp",
    "FIRRTLRegOp",
    "FIRRTLNodeOp",
    "FIRRTLConnectOp",
    "FIRRTLWhenOp",
    "FIRRTLInstanceOp",
    "WidthInference",
    "FIRRTL_OPS",
]

FIRRTL_DIALECT = Dialect("firrtl", get_default_context())


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


class FIRRTLType(Type):
    """Base class for the FIRRTL ground and aggregate types.

    ``width`` is ``None`` when the width is not known yet, which FIRRTL treats
    as a legal intermediate state rather than an error.
    """

    #: The dialect mnemonic, e.g. ``uint``.
    MNEMONIC: str = "firrtl"

    def __init__(self, width: Optional[int] = None) -> None:
        if width is not None:
            width = int(width)
            if width < 0:
                raise ValueError(f"FIRRTL width must be non-negative, got {width}")
        self.width = width

    def __str__(self) -> str:
        if self.width is None:
            return f"!firrtl.{self.MNEMONIC}"
        return f"!firrtl.{self.MNEMONIC}<{self.width}>"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return str(self)

    # -- widths -----------------------------------------------------------
    @property
    def is_width_known(self) -> bool:
        return self.width is not None

    def bitwidth(self) -> Optional[int]:
        return self.width

    def bit_count(self) -> int:
        """The concrete width, or ``0`` when it is still unknown.

        ``bit_count`` is the hook :func:`~src.circt.hw_dialect.bit_width_of`
        looks for, and that contract is "an integer", so an unknown width reads
        as zero there while :attr:`width` keeps the honest ``None``.
        """
        return int(self.width or 0)

    def with_width(self, width: Optional[int]) -> "FIRRTLType":
        """A copy of this type with ``width`` substituted."""
        return type(self)(width)

    @property
    def is_signed(self) -> bool:
        return False

    @property
    def is_ground(self) -> bool:
        return True

    def to_hw_type(self) -> Optional[Type]:
        """The ``hw`` type this lowers to, when the width is known."""
        if self.width is None or self.width == 0:
            return None
        return IntType(self.width)


class FIRRTLUIntType(FIRRTLType):
    """``!firrtl.uint<8>`` - an unsigned integer, possibly of unknown width."""

    MNEMONIC = "uint"


class FIRRTLSIntType(FIRRTLType):
    """``!firrtl.sint<8>`` - a two's-complement signed integer."""

    MNEMONIC = "sint"

    @property
    def is_signed(self) -> bool:
        return True


class FIRRTLClockType(FIRRTLType):
    """``!firrtl.clock`` - one wire, and never width-annotated."""

    MNEMONIC = "clock"

    def __init__(self) -> None:
        super().__init__(1)

    def __str__(self) -> str:
        return "!firrtl.clock"

    def with_width(self, width: Optional[int]) -> "FIRRTLClockType":
        return FIRRTLClockType()


class FIRRTLResetType(FIRRTLType):
    """``!firrtl.reset`` / ``!firrtl.asyncreset``."""

    MNEMONIC = "reset"

    def __init__(self, asynchronous: bool = False) -> None:
        super().__init__(1)
        self.asynchronous = bool(asynchronous)

    def __str__(self) -> str:
        return "!firrtl.asyncreset" if self.asynchronous else "!firrtl.reset"

    def with_width(self, width: Optional[int]) -> "FIRRTLResetType":
        return FIRRTLResetType(self.asynchronous)


class FIRRTLAnalogType(FIRRTLType):
    """``!firrtl.analog<1>`` - a bidirectional, non-digital net."""

    MNEMONIC = "analog"

    @property
    def is_ground(self) -> bool:
        return True


@dataclass
class FIRRTLBundleField:
    """One field of a bundle.  ``flip`` reverses the field's direction."""

    name: str
    type: Type
    flip: bool = False

    def __str__(self) -> str:
        prefix = "flip " if self.flip else ""
        return f"{prefix}{self.name}: {_inner_spelling(self.type)}"


def _inner_spelling(type: Optional[Type]) -> str:
    """Nested FIRRTL types drop the ``!firrtl.`` prefix, as FIRRTL prints them."""
    if type is None:
        return "?"
    text = str(type)
    return text[len("!firrtl.") :] if text.startswith("!firrtl.") else text


class FIRRTLBundleType(FIRRTLType):
    """``!firrtl.bundle<a: uint<1>, flip b: uint<8>>``."""

    MNEMONIC = "bundle"

    def __init__(
        self,
        fields: Optional[Sequence[Union[FIRRTLBundleField, Tuple[Any, ...]]]] = None,
    ) -> None:
        super().__init__(None)
        self.fields: List[FIRRTLBundleField] = [_as_field(f) for f in fields or ()]

    def __str__(self) -> str:
        inner = ", ".join(str(field) for field in self.fields)
        return f"!firrtl.bundle<{inner}>"

    # -- widths -----------------------------------------------------------
    @property
    def is_width_known(self) -> bool:
        return all(_width_of(field.type) is not None for field in self.fields)

    def bitwidth(self) -> Optional[int]:
        total = 0
        for field in self.fields:
            width = _width_of(field.type)
            if width is None:
                return None
            total += width
        return total

    def bit_count(self) -> int:
        return int(self.bitwidth() or 0)

    def with_width(self, width: Optional[int]) -> "FIRRTLBundleType":
        return FIRRTLBundleType(list(self.fields))

    @property
    def is_ground(self) -> bool:
        return False

    # -- fields -----------------------------------------------------------
    def field_names(self) -> List[str]:
        return [field.name for field in self.fields]

    def get_field(self, name: str) -> Optional[FIRRTLBundleField]:
        for field in self.fields:
            if field.name == name:
                return field
        return None

    def get_field_type(self, name: str) -> Optional[Type]:
        field = self.get_field(name)
        return field.type if field is not None else None

    def is_flipped(self, name: str) -> bool:
        field = self.get_field(name)
        return bool(field is not None and field.flip)

    def to_hw_type(self) -> Optional[Type]:
        width = self.bitwidth()
        return IntType(width) if width else None


class FIRRTLVectorType(FIRRTLType):
    """``!firrtl.vector<uint<8>, 4>``."""

    MNEMONIC = "vector"

    def __init__(self, element_type: Optional[Type] = None, count: int = 0) -> None:
        super().__init__(None)
        self.element_type = element_type
        self.count = int(count)

    def __str__(self) -> str:
        return f"!firrtl.vector<{_inner_spelling(self.element_type)}, {self.count}>"

    @property
    def is_width_known(self) -> bool:
        return _width_of(self.element_type) is not None

    def bitwidth(self) -> Optional[int]:
        element = _width_of(self.element_type)
        return None if element is None else element * self.count

    def bit_count(self) -> int:
        return int(self.bitwidth() or 0)

    def with_width(self, width: Optional[int]) -> "FIRRTLVectorType":
        return FIRRTLVectorType(self.element_type, self.count)

    @property
    def is_ground(self) -> bool:
        return False

    def element_at(self, index: int) -> Optional[Type]:
        if index < 0 or index >= self.count:
            raise IndexError(f"vector index {index} out of range for {self.count}")
        return self.element_type

    def to_hw_type(self) -> Optional[Type]:
        width = self.bitwidth()
        return IntType(width) if width else None


def _as_field(item: Union[FIRRTLBundleField, Tuple[Any, ...]]) -> FIRRTLBundleField:
    if isinstance(item, FIRRTLBundleField):
        return item
    name, ftype, *rest = item
    return FIRRTLBundleField(str(name), ftype, bool(rest[0]) if rest else False)


def _width_of(type: Optional[Type]) -> Optional[int]:
    """The width of ``type``, keeping FIRRTL's "unknown" distinct from zero."""
    if type is None:
        return None
    if isinstance(type, FIRRTLType):
        return type.bitwidth()
    width = bit_width_of(type)
    return width or None


for _mnemonic in ("uint", "sint", "clock", "reset", "asyncreset", "analog",
                  "bundle", "vector"):
    FIRRTL_DIALECT.register_type_parser(
        _mnemonic, lambda body, _m=_mnemonic: OpaqueType("firrtl", _m, body)
    )
del _mnemonic


# ---------------------------------------------------------------------------
# Operations
# ---------------------------------------------------------------------------


def _string_attribute(op: Operation, *names: str) -> str:
    """First present string-valued attribute out of ``names``."""
    for name in names:
        attr = op.attributes.get(name)
        if attr is not None:
            return str(attr.value)
    return ""


class FIRRTLCircuitOp(HWOp):
    """``firrtl.circuit "Top" { ... }`` - the top-level container."""

    OPERATION_NAME = "firrtl.circuit"
    TRAITS = (Trait.SYMBOL_TABLE, Trait.SINGLE_BLOCK, Trait.NO_TERMINATOR,
              Trait.ISOLATED_FROM_ABOVE)

    def __init__(
        self,
        name: Optional[str] = None,
        modules: Optional[Sequence[Operation]] = None,
        main_module: Optional[str] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("sym_name", StringAttr(name))
        if main_module:
            attrs.setdefault("main_module", StringAttr(main_module))
        super().__init__(attributes=attrs, location=location)
        block = self.add_region(Region()).add_block(Block())
        for module in modules or ():
            block.append(module)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @property
    def circuit_name(self) -> str:
        return _string_attribute(self, "sym_name", "name")

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def modules(self) -> List[Operation]:
        block = self.block
        if block is None:
            return []
        return [op for op in block.operations if op.name == FIRRTLModuleOp.OPERATION_NAME]

    def find_module(self, name: str) -> Optional[Operation]:
        wanted = name.lstrip("@")
        for module in self.modules:
            if _string_attribute(module, "sym_name") == wanted:
                return module
        return None

    @property
    def main_module(self) -> Optional[Operation]:
        """The module the circuit is named after, FIRRTL's entry point."""
        declared = _string_attribute(self, "main_module")
        if declared:
            found = self.find_module(declared)
            if found is not None:
                return found
        found = self.find_module(self.circuit_name)
        if found is not None:
            return found
        modules = self.modules
        return modules[0] if modules else None

    def verify_op(self) -> List[str]:
        if not self.circuit_name:
            return ["'firrtl.circuit' requires a name"]
        return []


class FIRRTLModuleOp(HWOp):
    """``firrtl.module @M(in %a: !firrtl.uint<8>, out %o: !firrtl.uint<8>)``.

    The parser lists ``firrtl.module`` in both ``GRAPH_REGION_OPS`` and
    ``PORT_LIST_OPS``, and the printer formats it with the hardware-module
    header, so the port encoding matches
    :class:`~src.circt.hw_dialect.HWModuleOp` exactly: ``sym_name``,
    ``function_type``, ``port_names`` and ``port_directions``.
    """

    OPERATION_NAME = "firrtl.module"
    TRAITS = (
        Trait.SYMBOL,
        Trait.ISOLATED_FROM_ABOVE,
        Trait.GRAPH_REGION,
        Trait.SINGLE_BLOCK,
    )

    def __init__(
        self,
        name: Optional[str] = None,
        ports: Optional[Sequence[Port]] = None,
        body: Optional[Sequence[Operation]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        port_list = [_as_port(port) for port in ports or ()]
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("sym_name", StringAttr(name))
        attrs["port_names"] = ArrayAttr([StringAttr(p.name) for p in port_list])
        attrs["port_directions"] = ArrayAttr(
            [StringAttr(p.direction.value) for p in port_list]
        )
        attrs["function_type"] = TypeAttr(
            FunctionType(
                [p.port_type for p in port_list if not p.is_output and p.port_type],
                [p.port_type for p in port_list if p.is_output and p.port_type],
            )
        )
        super().__init__(attributes=attrs, location=location)
        block = self.add_region(Region()).add_block(Block())
        for port in port_list:
            if not port.is_output:
                block.add_argument(port.port_type or FIRRTLUIntType(1), port.name)
        for op in body or ():
            block.append(op)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    # -- structure --------------------------------------------------------
    @property
    def module_name(self) -> str:
        return _string_attribute(self, "sym_name")

    @property
    def sym_name(self) -> str:
        return self.module_name

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        block = self.block
        return list(block.operations) if block is not None else []

    def append(self, op: Operation) -> Operation:
        block = self.block
        if block is None:
            block = self.add_region(Region()).add_block(Block())
        return block.append(op)

    @property
    def ports(self) -> List[Port]:
        names = self.attributes.get("port_names")
        directions = self.attributes.get("port_directions")
        ftype = self.attributes.get("function_type")
        signature = ftype.value if ftype is not None else None
        if not isinstance(names, ArrayAttr) or not isinstance(directions, ArrayAttr):
            return []
        inputs = list(signature.inputs) if signature is not None else []
        outputs = list(signature.results) if signature is not None else []
        result: List[Port] = []
        in_index = out_index = 0
        for name_attr, dir_attr in zip(names, directions):
            direction = Direction.parse(dir_attr.value)
            if direction is Direction.OUTPUT:
                ptype = outputs[out_index] if out_index < len(outputs) else None
                out_index += 1
            else:
                ptype = inputs[in_index] if in_index < len(inputs) else None
                in_index += 1
            result.append(Port(name_attr.value, ptype, direction))
        return result

    @property
    def input_ports(self) -> List[Port]:
        return [p for p in self.ports if not p.is_output]

    @property
    def output_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_output]

    def get_port(self, name: str) -> Optional[Port]:
        for port in self.ports:
            if port.name == name:
                return port
        return None

    # -- verification -----------------------------------------------------
    def verify_op(self) -> List[str]:
        errors: List[str] = []
        if not self.module_name:
            errors.append("'firrtl.module' requires a 'sym_name' attribute")
        seen: set = set()
        for port in self.ports:
            if port.name in seen:
                errors.append(f"Duplicate port name: {port.name}")
            seen.add(port.name)
        return errors


def _as_port(port: Union[Port, Tuple[Any, ...]]) -> Port:
    if isinstance(port, Port):
        return port
    name, ptype, *rest = port
    return Port(str(name), ptype, rest[0] if rest else Direction.INPUT)


class FIRRTLWireOp(HWOp):
    """``%w = firrtl.wire : !firrtl.uint<8>`` - a named, connectable net."""

    OPERATION_NAME = "firrtl.wire"
    TRAITS = (Trait.PURE,)

    wire_name: str = ""
    driven_value: int = 0

    def __init__(
        self,
        name: Optional[str] = None,
        wire_type: Optional[Type] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        width: int = 0,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = {}
        if name:
            attrs["name"] = StringAttr(name)
        types = list(result_types or ())
        if not types and wire_type is not None:
            types = [wire_type]
        super().__init__(
            operands=operands,
            result_types=types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.wire_name = name or ""
        self.driven_value = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.wire_name = _string_attribute(op, "name") or op.result_name
        op.driven_value = 0
        return op

    def connect(self, value: int) -> int:
        """Drive the wire, as ``firrtl.connect`` does."""
        self.driven_value = self.truncate(value)
        return self.driven_value

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        if self.num_operands:
            return self.truncate(self.read_operand(env or {}, 0))
        return self.truncate(self.driven_value)


class FIRRTLNodeOp(HWOp):
    """``%n = firrtl.node %x`` - a name bound to an existing value."""

    OPERATION_NAME = "firrtl.node"
    TRAITS = (Trait.PURE,)

    node_name: str = ""

    def __init__(
        self,
        name: Optional[str] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        width: int = 0,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = {}
        if name:
            attrs["name"] = StringAttr(name)
        super().__init__(
            operands=operands,
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.node_name = name or ""

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.node_name = _string_attribute(op, "name") or op.result_name
        return op

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.truncate(self.read_operand(env or {}, 0))


class FIRRTLRegOp(SeqOp):
    """``firrtl.reg``/``firrtl.regreset`` - a clocked register.

    Operand order follows the ``seq`` dialect so the same two-phase interface
    works: ``(input, clock[, reset, resetValue])``.  ``next_value`` computes what
    the register will latch, and ``commit`` writes it, so a FIRRTL register can
    be driven by the same cycle-accurate simulator as ``seq.compreg``.
    """

    OPERATION_NAME = "firrtl.reg"

    #: Operand indices.
    INPUT = 0
    CLOCK = 1
    RESET = 2
    RESET_VALUE = 3

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        clock: Union[Value, str] = "clk",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        current_value: int = 0,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            if reset is not None:
                ops.append(reset)
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("name", StringAttr(name))
        super().__init__(
            operands=ops,
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.reset_value = int(reset_value)
        self.current_value = int(current_value)
        self.cycles_ticked = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.reg_name = _string_attribute(op, "name") or op.result_name
        op.reset_value = 0
        op.current_value = 0
        op.cycles_ticked = 0
        return op

    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    def reset_active(self, env: SignalEnv) -> bool:
        if not self.has_reset:
            return False
        return bool(self.read_operand(env, self.RESET) & 1)

    def declared_reset_value(self, env: SignalEnv) -> int:
        if self.num_operands > self.RESET_VALUE:
            return self.read_operand(env, self.RESET_VALUE)
        return self.reset_value

    def next_value(self, env: SignalEnv) -> int:
        if self.reset_active(env):
            return self.truncate(self.declared_reset_value(env))
        return self.truncate(self.read_operand(env, self.INPUT, default=0))

    def reset_state(self, env: Optional[SignalEnv] = None) -> None:
        self.current_value = self.truncate(self.declared_reset_value(env or {}))
        self.cycles_ticked = 0

    def verify_op(self) -> List[str]:
        if self.num_operands < 2:
            return ["'firrtl.reg' expects at least an input and a clock operand"]
        return []


class FIRRTLConnectOp(HWOp):
    """``firrtl.connect %dest, %src`` - drive ``dest`` from ``src``.

    A connect produces no value; it is the FIRRTL spelling of assignment, so
    :meth:`apply` returns the value that would be driven rather than binding a
    result.
    """

    OPERATION_NAME = "firrtl.connect"

    #: Operand indices.
    DEST = 0
    SRC = 1

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        dest: Optional[Union[Value, str]] = None,
        src: Optional[Union[Value, str]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if dest is not None:
                ops.append(dest)
            if src is not None:
                ops.append(src)
        super().__init__(operands=ops, location=location)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @property
    def dest(self) -> Any:
        return self.get_operand(self.DEST) if self.num_operands > self.DEST else None

    @property
    def src(self) -> Any:
        return self.get_operand(self.SRC) if self.num_operands > self.SRC else None

    def destination_width(self) -> int:
        dest = self.dest
        if isinstance(dest, Value):
            return bit_width_of(dest.type)
        return 0

    def apply(self, env: Optional[SignalEnv] = None) -> int:
        """The value driven onto the destination, truncated to its width."""
        value = self.read_operand(env or {}, self.SRC, default=0)
        width = self.destination_width()
        return value & ((1 << width) - 1) if width else value

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.apply(env)

    def verify_op(self) -> List[str]:
        if self.num_operands != 2:
            return [f"'firrtl.connect' expects 2 operands, got {self.num_operands}"]
        return []


class FIRRTLWhenOp(HWOp):
    """``firrtl.when %cond { ... } else { ... }``."""

    OPERATION_NAME = "firrtl.when"

    def __init__(
        self,
        condition: Optional[Union[Value, str]] = None,
        then_body: Optional[Sequence[Operation]] = None,
        else_body: Optional[Sequence[Operation]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops and condition is not None:
            ops.append(condition)
        super().__init__(operands=ops, location=location)
        for body in (then_body, else_body):
            if body is None:
                continue
            block = self.add_region(Region()).add_block(Block())
            for op in body:
                block.append(op)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @property
    def condition(self) -> Any:
        return self.get_operand(0) if self.num_operands else None

    @property
    def then_region(self) -> Optional[Region]:
        return self.regions[0] if self.regions else None

    @property
    def else_region(self) -> Optional[Region]:
        return self.regions[1] if len(self.regions) > 1 else None

    @property
    def has_else(self) -> bool:
        region = self.else_region
        return region is not None and bool(region.blocks)

    @staticmethod
    def _body_of(region: Optional[Region]) -> List[Operation]:
        if region is None or not region.blocks:
            return []
        return list(region.blocks[0].operations)

    @property
    def then_body(self) -> List[Operation]:
        return self._body_of(self.then_region)

    @property
    def else_body(self) -> List[Operation]:
        return self._body_of(self.else_region)

    def condition_value(self, env: Optional[SignalEnv] = None) -> int:
        return self.read_operand(env or {}, 0, default=0) & 1

    def taken_branch(self, env: Optional[SignalEnv] = None) -> str:
        return "then" if self.condition_value(env) else "else"

    def taken_body(self, env: Optional[SignalEnv] = None) -> List[Operation]:
        return self.then_body if self.condition_value(env) else self.else_body


class FIRRTLInstanceOp(HWOp):
    """``firrtl.instance name @Module`` - an instantiation with port bindings."""

    OPERATION_NAME = "firrtl.instance"

    instance_name: str = ""
    target_module: str = ""

    def __init__(
        self,
        instance_name: Optional[str] = None,
        module_name: Optional[str] = None,
        port_bindings: Optional[Dict[str, Any]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = {}
        if instance_name:
            attrs["instance_name"] = StringAttr(instance_name)
        if module_name:
            attrs["module_name"] = StringAttr(module_name.lstrip("@"))
        super().__init__(
            operands=operands,
            result_types=result_types,
            attributes=attrs,
            location=location,
        )
        self.instance_name = instance_name or ""
        self.target_module = (module_name or "").lstrip("@")
        self.port_bindings: Dict[str, Any] = dict(port_bindings or {})

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        op.instance_name = _string_attribute(op, "instance_name", "name")
        op.target_module = _string_attribute(op, "module_name", "sym_name")
        op.port_bindings = {}
        return op

    def bind(self, port_name: str, value: Any) -> None:
        self.port_bindings[port_name] = value

    def binding(self, port_name: str) -> Any:
        return self.port_bindings.get(port_name)

    def resolve_module(self, circuit: Operation) -> Optional[Operation]:
        """Find the instantiated module inside ``circuit``."""
        finder = getattr(circuit, "find_module", None)
        if callable(finder):
            return finder(self.target_module)
        found: List[Operation] = []

        def visit(op: Operation) -> None:
            if op.name == FIRRTLModuleOp.OPERATION_NAME and _string_attribute(
                op, "sym_name"
            ) == self.target_module:
                found.append(op)

        circuit.walk(visit)
        return found[0] if found else None

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"FIRRTLInstanceOp({self.instance_name} : {self.target_module})"


# ---------------------------------------------------------------------------
# Width inference
# ---------------------------------------------------------------------------


class WidthInference:
    """Propagates FIRRTL widths through an operation graph to a fixed point.

    FIRRTL lets a design leave widths off and requires the compiler to work them
    out.  The per-operation rules are fixed by the specification::

        add, sub   -> max(l, r) + 1      (room for the carry / borrow)
        mul        -> l + r
        div        -> l  (+1 signed, for the -2^n / -1 case)
        rem        -> min(l, r)
        and/or/xor -> max(l, r)
        cat        -> l + r
        cmp        -> 1
        dshl       -> l + (2 ** r - 1)   (worst-case dynamic shift)

    Widths are propagated repeatedly because a graph region may use a value
    before defining it; the loop stops when a sweep changes nothing.
    """

    #: Safety net for the fixed-point loop.
    MAX_ITERATIONS = 16

    #: Operation mnemonics grouped by the rule that gives their result width.
    ADDITIVE_OPS = frozenset({"add", "sub", "addi", "subi"})
    PRODUCT_OPS = frozenset({"mul", "muli", "cat", "concat"})
    DIVIDE_OPS = frozenset({"div", "divu", "divs"})
    REMAINDER_OPS = frozenset({"rem", "mod", "modu", "mods"})
    BITWISE_OPS = frozenset({"and", "or", "xor", "andi", "ori", "xori"})
    COMPARE_OPS = frozenset({"cmp", "icmp", "eq", "neq", "lt", "leq", "gt", "geq"})
    DYNAMIC_SHIFT_OPS = frozenset({"dshl"})
    STATIC_SHIFT_OPS = frozenset({"shl", "shr", "shru", "shrs"})

    def __init__(self, widths: Optional[Dict[str, Optional[int]]] = None) -> None:
        self.widths: Dict[str, Optional[int]] = dict(widths or {})
        self.constraints: List[Tuple[str, str]] = []
        self.iterations = 0

    # -- known widths -----------------------------------------------------
    def set_width(self, name: str, width: Optional[int]) -> Optional[int]:
        self.widths[name] = None if width is None else int(width)
        return self.widths[name]

    def get_width(self, name: str) -> Optional[int]:
        return self.widths.get(name)

    def declare(self, name: str, type: Optional[Type] = None) -> Optional[int]:
        """Record a value and, when its type says so, its width."""
        return self.set_width(name, _width_of(type))

    def constrain(self, name: str, same_as: str) -> None:
        """Require two values to end up the same width (a connect, say)."""
        self.constraints.append((name, same_as))

    # -- the rules --------------------------------------------------------
    def infer_binary(
        self,
        op_kind: str,
        lhs_width: Optional[int],
        rhs_width: Optional[int],
        signed: bool = False,
    ) -> Optional[int]:
        """The result width of ``op_kind`` given its operand widths."""
        kind = op_kind.split(".")[-1].lower()
        if kind in self.COMPARE_OPS:
            return 1
        if lhs_width is None or rhs_width is None:
            # A dynamic shift only needs its shift amount to be known.
            if kind in self.DYNAMIC_SHIFT_OPS and lhs_width is not None:
                return None
            return None
        left, right = int(lhs_width), int(rhs_width)
        if kind in self.ADDITIVE_OPS:
            return max(left, right) + 1
        if kind in self.PRODUCT_OPS:
            return left + right
        if kind in self.DIVIDE_OPS:
            return left + 1 if signed else left
        if kind in self.REMAINDER_OPS:
            return min(left, right)
        if kind in self.BITWISE_OPS:
            return max(left, right)
        if kind in self.DYNAMIC_SHIFT_OPS:
            return left + (1 << right) - 1
        if kind in self.STATIC_SHIFT_OPS:
            return left
        # Anything else keeps its operands' common width.
        return max(left, right)

    def infer_unary(self, op_kind: str, width: Optional[int]) -> Optional[int]:
        kind = op_kind.split(".")[-1].lower()
        if kind in ("parity", "orr", "andr", "xorr", "not_zero"):
            return 1
        if kind in ("neg",):
            return None if width is None else int(width) + 1
        if kind in ("cvt",):
            return None if width is None else int(width) + 1
        return width

    # -- whole-module inference --------------------------------------------
    def infer_module(self, module: Operation) -> Dict[str, Optional[int]]:
        """Propagate widths through ``module``'s body until nothing changes.

        Returns the map of value name to inferred width, leaving ``None`` where
        the width is still unknown.
        """
        for port in getattr(module, "ports", []) or []:
            self.declare(port.name, port.port_type)
        block = getattr(module, "block", None)
        operations = list(block.operations) if block is not None else []
        for op in operations:
            for result in op.results:
                if result.name and result.name not in self.widths:
                    self.declare(result.name, result.type)

        for iteration in range(1, self.MAX_ITERATIONS + 1):
            self.iterations = iteration
            if not self._sweep(operations):
                break
        return dict(self.widths)

    def _sweep(self, operations: Sequence[Operation]) -> bool:
        changed = False
        for op in operations:
            for result in op.results:
                name = result.name
                if not name or self.widths.get(name) is not None:
                    continue
                inferred = self._infer_result(op, result)
                if inferred is None:
                    continue
                self.widths[name] = int(inferred)
                changed = True
        for name, same_as in self.constraints:
            source = self.widths.get(same_as)
            if source is not None and self.widths.get(name) is None:
                self.widths[name] = source
                changed = True
        return changed

    def _infer_result(self, op: Operation, result: Any) -> Optional[int]:
        declared = _width_of(result.type)
        if declared is not None:
            return declared
        operand_widths = [self._operand_width(operand) for operand in op.operands]
        signed = isinstance(result.type, FIRRTLSIntType)
        if len(operand_widths) >= 2:
            return self.infer_binary(op.name, operand_widths[0], operand_widths[1], signed)
        if len(operand_widths) == 1:
            return self.infer_unary(op.name, operand_widths[0])
        return None

    def _operand_width(self, operand: Any) -> Optional[int]:
        if isinstance(operand, Value):
            name = getattr(operand, "name", None)
            if name and self.widths.get(name) is not None:
                return self.widths[name]
            return _width_of(operand.type)
        return self.widths.get(str(operand))

    # -- reporting --------------------------------------------------------
    def unresolved(self) -> List[str]:
        return sorted(name for name, width in self.widths.items() if width is None)

    def is_fully_resolved(self) -> bool:
        return not self.unresolved()

    def to_text(self) -> str:
        return "\n".join(
            f"{name} : {'?' if width is None else width}"
            for name, width in sorted(self.widths.items())
        )

    def __len__(self) -> int:
        return len(self.widths)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return (
            f"<WidthInference known={len(self.widths) - len(self.unresolved())}"
            f"/{len(self.widths)} iterations={self.iterations}>"
        )


